t() {
  local key="$1"
  shift || true
  local pair text
  if [[ "$DEPLOY_LANG" == "zh" && -v "__DEPLOY_I18N_ZH[$key]" ]]; then
    i18n_print "${__DEPLOY_I18N_ZH[$key]}" "$@"
    return 0
  fi
  if [[ -v "__DEPLOY_I18N_EN[$key]" ]]; then
    i18n_print "${__DEPLOY_I18N_EN[$key]}" "$@"
    return 0
  fi
  pair="$(__deploy_i18n_message "$key")"
  if [[ "$DEPLOY_LANG" == "zh" ]]; then
    text="${pair#*|}"
  else
    text="${pair%%|*}"
  fi
  i18n_print "$text" "$@"
}

# ----- lib/logging.sh -----

RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
BOLD='\033[1m'
NC='\033[0m'

if [[ -n "${NO_COLOR:-}" || "${TERM:-}" == "dumb" ]]; then
  RED=''
  GREEN=''
  YELLOW=''
  BLUE=''
  CYAN=''
  BOLD=''
  NC=''
fi

info() { echo -e "${BLUE}[i]${NC} $*" >&2; }
success() { echo -e "${GREEN}[+]${NC} $*" >&2; }
warn() { echo -e "${YELLOW}[!]${NC} $*" >&2; }
error() { echo -e "${RED}[x]${NC} $*" >&2; exit 1; }
step() { echo -e "\n${CYAN}${BOLD}== $* ==${NC}" >&2; }
prompt() { echo -ne "${YELLOW}[?]${NC} $* " >&2; }

# ----- lib/fs.sh -----

require_root() {
  local action="${1:-}"
  [[ ${EUID:-$(id -u)} -eq 0 ]] || error "$(t error.root_required "$0" "$action")"
}

require_command() {
  local command_name="$1"
  command -v "$command_name" >/dev/null 2>&1 || error "$(t error.command_required "$command_name")"
}

is_safe_path() {
  local path="${1:-}"
  [[ -n "$path" ]] || return 1
  [[ "$path" = /* ]] || return 1

  while [[ "$path" != "/" && "$path" == */ ]]; do
    path="${path%/}"
  done

  case "$path" in
    /|.|..|*'/../'*|*'/..'|*'/./'*|*'/.')
      return 1
      ;;
    /bin|/boot|/dev|/etc|/home|/lib|/lib64|/opt|/proc|/root|/run|/sbin|/sys|/tmp|/usr|/var|/usr/local)
      return 1
      ;;
  esac

  # Reject every top-level directory (for example /srv, /mnt, /data):
  # deployment and deletion targets must always live inside a named
  # subdirectory.  This keeps the guard fail-closed instead of relying on an
  # exhaustive blacklist of mount points.
  local remainder="${path#/}"
  [[ "$remainder" == */* ]] || return 1

  # Additional nested system directories that must never be targets.
  case "$path" in
    /var/lib|/var/log|/var/www|/var/cache|/var/run|/var/spool|/usr/local/bin|/usr/local/lib|/usr/share|/mnt|/media|/srv|/data|/backup|/www|/export|/pool)
      return 1
      ;;
  esac
  return 0
}

require_safe_path() {
  local name="$1"
  local path="$2"
  is_safe_path "$path" || error "$(t error.unsafe_path "$name" "${path:-empty}")"
}

safe_rm_dir() {
  local path="$1"
  local name="${2:-path}"
  while [[ "$path" != "/" && "$path" == */ ]]; do
    path="${path%/}"
  done
  require_safe_path "$name" "$path"
  [[ -e "$path" || -L "$path" ]] || return 0
  [[ -d "$path" || -L "$path" ]] || return 1
  rm -rf -- "$path"
}

# ----- lib/atomic.sh -----

atomic_write_file() {
  local target_path="$1"
  local mode="${2:-}"
  local owner="${3:-}"
  local target_dir target_tmp
  target_dir="$(dirname "$target_path")"
  if ! mkdir -p "$target_dir"; then
    return 1
  fi
  if ! target_tmp="$(mktemp "${target_dir}/.$(basename "$target_path").XXXXXX")"; then
    return 1
  fi
  if ! cat > "$target_tmp"; then
    rm -f "$target_tmp"
    return 1
  fi
  if [[ -n "$mode" ]] && ! chmod "$mode" "$target_tmp"; then
    rm -f "$target_tmp"
    return 1
  fi
  if [[ -n "$owner" ]] && ! chown "$owner" "$target_tmp" 2>/dev/null; then
    rm -f "$target_tmp"
    return 1
  fi
  if ! mv "$target_tmp" "$target_path"; then
    rm -f "$target_tmp"
    return 1
  fi
}

atomic_copy_file() {
  local source_path="$1"
  local target_path="$2"
  local mode="${3:-}"
  local owner="${4:-}"
  local target_dir target_tmp
  [[ -f "$source_path" ]] || return 1
  target_dir="$(dirname "$target_path")"
  if ! mkdir -p "$target_dir"; then
    return 1
  fi
  if ! target_tmp="$(mktemp "${target_path}.XXXXXX")"; then
    return 1
  fi
  if ! cp "$source_path" "$target_tmp"; then
    rm -f "$target_tmp"
    return 1
  fi
  if [[ -n "$mode" ]] && ! chmod "$mode" "$target_tmp"; then
    rm -f "$target_tmp"
    return 1
  fi
  if [[ -n "$owner" ]] && ! chown "$owner" "$target_tmp" 2>/dev/null; then
    rm -f "$target_tmp"
    return 1
  fi
  if ! mv "$target_tmp" "$target_path"; then
    rm -f "$target_tmp"
    return 1
  fi
}

atomic_symlink() {
  local target_path="$1"
  local link_path="$2"
  local link_dir link_tmp
  link_dir="$(dirname "$link_path")"
  if ! mkdir -p "$link_dir"; then
    return 1
  fi
  if ! link_tmp="$(mktemp "${link_path}.XXXXXX")"; then
    return 1
  fi
  rm -f "$link_tmp"
  if ! ln -s "$target_path" "$link_tmp" || ! mv -Tf "$link_tmp" "$link_path"; then
    rm -f "$link_tmp"
    return 1
  fi
}

# ----- lib/binary.sh -----

app_binary_restore_moved_backup() {
  local backup_path="$1"
  local restore_tmp
  [[ -n "$backup_path" && -f "$backup_path" ]] || return 0
  [[ ! -e "$BIN_PATH" ]] || return 1
  if ! restore_tmp="$(mktemp "${BIN_PATH}.restore.XXXXXX")"; then
    return 1
  fi
  if ! cp "$backup_path" "$restore_tmp"; then
    rm -f "$restore_tmp"
    return 1
  fi
  if ! chmod +x "$restore_tmp" \
      || ! chown "${SERVICE_USER}:${SERVICE_USER}" "$restore_tmp" \
      || ! mv "$restore_tmp" "$BIN_PATH"; then
    rm -f "$restore_tmp"
    return 1
  fi
  rm -f "$backup_path"
}

app_binary_install_candidate() {
  local tmp_bin="$1"
  local backup_path="${2:-}"
  if [[ -n "$backup_path" && -f "$BIN_PATH" ]]; then
    if ! mv "$BIN_PATH" "$backup_path"; then
      rm -f "$tmp_bin"
      return 1
    fi
  fi
  if ! mv "$tmp_bin" "$BIN_PATH"; then
    rm -f "$tmp_bin"
    app_binary_restore_moved_backup "$backup_path" || return 1
    return 1
  fi
  if ! chmod +x "$BIN_PATH" || ! chown "${SERVICE_USER}:${SERVICE_USER}" "$BIN_PATH"; then
    rm -f "$BIN_PATH"
    app_binary_restore_moved_backup "$backup_path" || return 1
    return 1
  fi
}

app_binary_restore_backup() {
  local backup_path="$1"
  local restore_tmp
  [[ -f "$backup_path" ]] || return 1
  if ! restore_tmp="$(mktemp "${BIN_PATH}.restore.XXXXXX")"; then
    return 1
  fi
  if ! cp "$backup_path" "$restore_tmp"; then
    rm -f "$restore_tmp"
    return 1
  fi
  if ! chmod +x "$restore_tmp" \
      || ! chown "${SERVICE_USER}:${SERVICE_USER}" "$restore_tmp" \
      || ! mv "$restore_tmp" "$BIN_PATH"; then
    rm -f "$restore_tmp"
    return 1
  fi
}

app_binary_backup_current() {
  local backup_path="$1"
  atomic_copy_file "$BIN_PATH" "$backup_path"
}

# ----- lib/lock.sh -----

declare -ga __DEPLOY_EXIT_HANDLERS=()

deploy_add_exit_handler() {
  local handler="$1"
  [[ -n "$handler" ]] || return 0
  __DEPLOY_EXIT_HANDLERS+=("$handler")
  trap '__deploy_run_exit_handlers' EXIT
}

__deploy_set_exit_status() {
  return "$1"
}

__deploy_run_exit_handlers() {
  local status=$? handler index
  if [[ -n "${__DEPLOY_EXIT_STATUS:-}" ]]; then
    status="$__DEPLOY_EXIT_STATUS"
  fi
  unset __DEPLOY_EXIT_STATUS
  trap - EXIT
  for (( index=${#__DEPLOY_EXIT_HANDLERS[@]} - 1; index >= 0; index-- )); do
    handler="${__DEPLOY_EXIT_HANDLERS[$index]}"
    # Protect the status-setting return from errexit while keeping it visible
    # as `$?` to the handler.
    if __deploy_set_exit_status "$status"; then
      "$handler" || true
    else
      "$handler" || true
    fi
  done
  exit "$status"
}

acquire_lock() {
  local lock_file="${1:-${LOCK_FILE:-}}"
  [[ -n "$lock_file" ]] || return 0
  if ! mkdir -p "$(dirname "$lock_file")"; then
    error "$(t error.lock_failed "$lock_file")"
  fi
  if ! exec 9>"$lock_file"; then
    error "$(t error.lock_failed "$lock_file")"
  fi
  flock -n 9 || error "$(t error.lock_failed "$lock_file")"
  if [[ "${__DEPLOY_LOCK_EXIT_REGISTERED:-0}" != "1" ]]; then
    deploy_add_exit_handler release_lock
    __DEPLOY_LOCK_EXIT_REGISTERED=1
  fi
}

release_lock() {
  flock -u 9 2>/dev/null || true
  exec 9>&- 2>/dev/null || true
}

# ----- lib/config.sh -----

sanitize_conf_val() {
  local newline=$'\n'
  local carriage_return=$'\r'
  local value="${1%%"${newline}"*}"
  value="${value%%"${carriage_return}"*}"
  value="${value//\"/}"
  echo "$value"
}

trim_conf_token() {
  local value="$1"
  value="${value#"${value%%[![:space:]]*}"}"
  value="${value%"${value##*[![:space:]]}"}"
  printf '%s' "$value"
}

config_file_is_safe() {
  local conf_file="$1"
  [[ -f "$conf_file" ]] || return 0

  if command -v stat >/dev/null 2>&1; then
    local owner mode
    owner="$(stat -c '%U' "$conf_file" 2>/dev/null || echo unknown)"
    mode="$(stat -c '%a' "$conf_file" 2>/dev/null || echo 777)"
    [[ "$owner" == "root" ]] || error "$(t error.config_owner "$conf_file")"
    [[ "$mode" == "600" || "$mode" == "400" ]] || error "$(t error.config_permission "$conf_file")"
  fi
  return 0
}

load_config_file() {
  local conf_file="$1"
  # Character ranges in regexes are collation-dependent: under en_US.UTF-8 /
  # zh_CN.UTF-8, [A-Z0-9] also matches lowercase. Pin the C locale so config
  # keys must be uppercase on every server locale.
  local LC_ALL=C
  shift
  local -a allowed_keys=("$@")
  [[ -f "$conf_file" ]] || return 0
  config_file_is_safe "$conf_file" || return 1

  local line key value allowed
  while IFS= read -r line || [[ -n "$line" ]]; do
    line="${line%$'\r'}"
    [[ "$line" =~ ^[[:space:]]*(#|$) || "$line" != *=* ]] && continue
    key="$(trim_conf_token "${line%%=*}")"
    if [[ ! "$key" =~ ^[A-Z_][A-Z0-9_]*$ ]]; then
      warn "$(t warn.config_invalid_key "$key")"
      continue
    fi
    value="$(trim_conf_token "${line#*=}")"
    if [[ "$value" =~ ^\"(.*)\"$ ]]; then
      value="${BASH_REMATCH[1]}"
    fi
    allowed=false
    local allowed_key
    for allowed_key in "${allowed_keys[@]}"; do
      if [[ "$key" == "$allowed_key" ]]; then
        allowed=true
        break
      fi
    done
    $allowed || { warn "$(t warn.config_unknown_key "$key")"; continue; }
    # printf -v would clobber the deployment shell's own state for reserved
    # names; the allow-list normally gates keys, but keep a defense-in-depth
    # guard so future CONFIG_KEYS cannot expose IFS/PATH and similar.
    case "$key" in
      IFS|PATH|BASH_ENV|ENV|SHELLOPTS|BASHOPTS|PS4|CDPATH|GLOBIGNORE)
        warn "$(t warn.config_reserved_key "$key")"
        continue
        ;;
    esac
    # A blank value means "not configured": keep the script default instead of
    # clobbering it. Older configs can store empty placeholders for keys that
    # later gained pinned defaults (e.g. EXTRACT_TOOL_SHA256); applying them
    # would make validation fail.
    [[ -z "$value" ]] && continue
    printf -v "$key" '%s' "$value"
  done < "$conf_file"
}

write_config_file() {
  local conf_file="$1"
  shift
  local tmp_file=""
  if ! tmp_file="$(mktemp "${conf_file}.tmp.XXXXXX")"; then
    return 1
  fi
  if ! chmod 600 "$tmp_file"; then
    rm -f "$tmp_file"
    return 1
  fi
  local key value
  for key in "$@"; do
    value="$(sanitize_conf_val "${!key:-}")"
    if ! printf '%s="%s"\n' "$key" "$value" >> "$tmp_file"; then
      rm -f "$tmp_file"
      return 1
    fi
  done
  if ! chown root:root "$tmp_file" 2>/dev/null; then
    rm -f "$tmp_file"
    return 1
  fi
  if ! mv "$tmp_file" "$conf_file"; then
    rm -f "$tmp_file"
    return 1
  fi
}

# ----- lib/service.sh -----

wait_for_service() {
  local service_name="$1"
  local timeout="${2:-20}"
  local elapsed=0
  while (( elapsed < timeout )); do
    if systemctl is-active --quiet "$service_name"; then
      return 0
    fi
    if systemctl is-failed --quiet "$service_name"; then
      return 1
    fi
    sleep 1
    elapsed=$((elapsed + 1))
  done
  return 1
}

systemd_write_unit() {
  local unit_path="$1"
  atomic_write_file "$unit_path" 644 root:root
}

service_status_label() {
  local service_name="$1"
  if systemctl is-active --quiet "$service_name" 2>/dev/null; then
    t status.active
  elif systemctl list-unit-files --no-legend --no-pager "$service_name.service" 2>/dev/null \
      | awk '{print $1}' \
      | grep -Fxq "$service_name.service"; then
    t status.inactive
  else
    t status.unknown
  fi
}

# ----- lib/network.sh -----

check_connectivity_urls() {
  local url
  for url in "$@"; do
    if curl -fsSL --max-time 8 -o /dev/null "$url" 2>/dev/null; then
      return 0
    fi
  done
  return 1
}

# Checks that at least one of the given endpoints is reachable; when none
# respond, fails the script through the given i18n error key.
app_check_connectivity() {
  local error_key="$1"
  shift
  if ! check_connectivity_urls "$@"; then
    error "$(t "$error_key")"
  fi
}

# Extracts the "tag_name" field from a GitHub releases/latest JSON payload.
# Pass --strip-v to drop a leading "v" (for example "v1.2.3" -> "1.2.3").
# Prints nothing when the payload has no parseable tag_name.
json_tag_name() {
  local json="$1" strip_v=false tag
  if [[ "${2:-}" == "--strip-v" ]]; then
    strip_v=true
  fi
  if echo "test" | grep -qP 'test' 2>/dev/null; then
    tag=$(printf '%s' "$json" | grep -oP '"tag_name"\s*:\s*"\K[^"]+' 2>/dev/null | head -1 || true)
  fi
  if [[ -z "${tag:-}" ]]; then
    tag=$(printf '%s' "$json" | grep '"tag_name"' | head -1 \
      | sed 's/.*"tag_name"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/' 2>/dev/null || true)
  fi
  if $strip_v; then
    tag="${tag#v}"
  fi
  printf '%s\n' "$tag"
}

# Fetches the latest release tag for a GitHub repository (owner/repo).
# The checked variant is intentionally silent so JSON-producing callers can
# handle failures without contaminating stdout. GITHUB_TOKEN, when present,
# is passed to curl only and is never logged or returned.
github_latest_release_tag_checked() {
  local repo="$1" json tag timeout_seconds
  local -a curl_args
  [[ "$repo" =~ ^[A-Za-z0-9._-]+/[A-Za-z0-9._-]+$ ]] || return 2
  timeout_seconds="${DEPLOY_GITHUB_API_TIMEOUT_SECONDS:-15}"
  [[ "$timeout_seconds" =~ ^[0-9]+$ && "$timeout_seconds" -gt 0 ]] || timeout_seconds=15
  curl_args=(-fsSL --max-time "$timeout_seconds" -H 'Accept: application/vnd.github+json')
  [[ -n "${GITHUB_TOKEN:-}" ]] && curl_args+=(-H "Authorization: Bearer ${GITHUB_TOKEN}")
  json="$(curl "${curl_args[@]}" "https://api.github.com/repos/${repo}/releases/latest" 2>/dev/null)" || return 1
  tag="$(json_tag_name "$json")"
  [[ "${tag:-}" =~ ^v?[0-9] ]] || return 2
  printf '%s\n' "$tag"
}

# Compatibility wrapper for existing lifecycle paths. It retains the prior
# warning-and-empty-output contract while delegating request handling to the
# silent helper used by the central version checker.
github_latest_release_tag() {
  local repo="$1" warn_key="$2" tag
  if ! tag="$(github_latest_release_tag_checked "$repo")"; then
    warn "$(t "$warn_key")"
    printf '\n'
    return 0
  fi
  printf '%s\n' "$tag"
}

is_valid_dns_name() {
  local name="${1:-}"
  # Character classes are collation-dependent: under UTF-8 locales
  # [A-Za-z0-9-] also matches accented characters. Pin C so DNS names stay ASCII.
  local LC_ALL=C
  [[ -n "$name" && ${#name} -le 253 ]] || return 1
  [[ "$name" != *..* ]] || return 1
  [[ "$name" =~ ^[A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*$ ]] || return 1
  [[ "$name" == *.* ]] || return 1
  return 0
}

# ── Unified port detection ────────────────────────────────────────

# Returns 0 when a process is listening on the given TCP port.
port_is_listening() {
  local port="$1"
  if command -v ss >/dev/null 2>&1; then
    ss -ltn "( sport = :$port )" 2>/dev/null | tail -n +2 | grep -q .
  elif command -v lsof >/dev/null 2>&1; then
    lsof -iTCP:"$port" -sTCP:LISTEN -Pn >/dev/null 2>&1
  else
    return 1
  fi
}

# Prints the process name (or pid/name from ss) bound to the port.
# Returns 0 when a process was identified, 1 otherwise (the caller reports
# the owner as unknown).
port_listening_process() {
  local port="$1" owner=""
  if command -v ss >/dev/null 2>&1; then
    owner="$(ss -ltnp "( sport = :$port )" 2>/dev/null | awk 'NR>1{
      n=$NF
      start=index(n, "\"")
      if (start > 0) {
        rest=substr(n, start + 1)
        stop=index(rest, "\"")
        if (stop > 0) print substr(rest, 1, stop - 1)
      }
      exit
    }')" || true
  elif command -v lsof >/dev/null 2>&1; then
    owner="$(lsof -iTCP:"$port" -sTCP:LISTEN -Pn 2>/dev/null | awk 'NR>1{print $1; exit}')" || true
  fi
  [[ -n "$owner" ]] || return 1
  printf '%s\n' "$owner"
  return 0
}

# Warns when a port is already in use.  Does NOT abort — the caller
# decides whether to proceed.  Pass an optional label for the port
# (e.g. "Backend port").
#
# This helper only warns: it always returns 0 so callers may invoke it as a
# bare command under `set -e` without aborting when the port is free.
app_check_port_conflict() {
  local port="$1"
  local label="${2:-Port $port}"
  if port_is_listening "$port"; then
    local owner
    owner=$(port_listening_process "$port" 2>/dev/null || echo "unknown")
    warn "$(t warn.port_in_use "$label" "$owner")"
    warn "$(t warn.port_release_hint)"
  fi
  return 0
}

# ----- lib/version.sh -----

# Strict Semantic Version helpers. Callers must only use these helpers when an
# application's release policy explicitly declares its tags comparable.

deploy_version_normalize() {
  local value="${1:-}" normalized prerelease
  local LC_ALL=C

  [[ "$value" =~ ^v?([0]|[1-9][0-9]*)\.([0]|[1-9][0-9]*)\.([0]|[1-9][0-9]*)(-([0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*))?(\+([0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*))?$ ]] || return 1

  normalized="${value#v}"
  prerelease="${BASH_REMATCH[5]:-}"
  if [[ -n "$prerelease" ]]; then
    local identifier
    IFS='.' read -r -a _deploy_version_identifiers <<< "$prerelease"
    for identifier in "${_deploy_version_identifiers[@]}"; do
      [[ "$identifier" =~ ^[0-9]+$ && "$identifier" != "0" && "$identifier" == 0* ]] && return 1
    done
  fi

  # Keep valid build metadata in normalized output. SemVer comparison ignores it.
  printf '%s\n' "$normalized"
}

deploy_version_is_stable() {
  local normalized
  normalized="$(deploy_version_normalize "${1:-}")" || return 1
  [[ "$normalized" != *-* ]]
}

deploy_version_compare_decimal() {
  local left="$1" right="$2"
  local LC_ALL=C

  if (( ${#left} < ${#right} )); then
    printf '%s\n' -1
  elif (( ${#left} > ${#right} )); then
    printf '%s\n' 1
  elif [[ "$left" < "$right" ]]; then
    printf '%s\n' -1
  elif [[ "$left" > "$right" ]]; then
    printf '%s\n' 1
  else
    printf '%s\n' 0
  fi
}

deploy_version_compare_identifier() {
  local left="$1" right="$2"
  local LC_ALL=C

  if [[ "$left" =~ ^[0-9]+$ && "$right" =~ ^[0-9]+$ ]]; then
    deploy_version_compare_decimal "$left" "$right"
  elif [[ "$left" =~ ^[0-9]+$ ]]; then
    printf '%s\n' -1
  elif [[ "$right" =~ ^[0-9]+$ ]]; then
    printf '%s\n' 1
  elif [[ "$left" < "$right" ]]; then
    printf '%s\n' -1
  elif [[ "$left" > "$right" ]]; then
    printf '%s\n' 1
  else
    printf '%s\n' 0
  fi
}

# Prints -1 when the first version is older, 0 when equal, and 1 when newer.
# Invalid versions return status 2 and never silently fall back to lexical order.
deploy_version_compare() {
  local left right left_core right_core left_pre right_pre result
  local -a left_parts right_parts left_identifiers right_identifiers
  local index max_identifiers

  left="$(deploy_version_normalize "${1:-}")" || return 2
  right="$(deploy_version_normalize "${2:-}")" || return 2
  left_core="${left%%[-+]*}"
  right_core="${right%%[-+]*}"
  left_pre=""
  right_pre=""
  [[ "$left" == *-* ]] && left_pre="${left#*-}" && left_pre="${left_pre%%+*}"
  [[ "$right" == *-* ]] && right_pre="${right#*-}" && right_pre="${right_pre%%+*}"

  IFS='.' read -r -a left_parts <<< "$left_core"
  IFS='.' read -r -a right_parts <<< "$right_core"
  for index in 0 1 2; do
    result="$(deploy_version_compare_decimal "${left_parts[$index]}" "${right_parts[$index]}")"
    [[ "$result" == 0 ]] || { printf '%s\n' "$result"; return 0; }
  done

  if [[ -z "$left_pre" && -z "$right_pre" ]]; then
    printf '%s\n' 0
    return 0
  fi
  [[ -z "$left_pre" ]] && { printf '%s\n' 1; return 0; }
  [[ -z "$right_pre" ]] && { printf '%s\n' -1; return 0; }

  IFS='.' read -r -a left_identifiers <<< "$left_pre"
  IFS='.' read -r -a right_identifiers <<< "$right_pre"
  max_identifiers=${#left_identifiers[@]}
  (( ${#right_identifiers[@]} > max_identifiers )) && max_identifiers=${#right_identifiers[@]}
  for ((index = 0; index < max_identifiers; index++)); do
    if (( index >= ${#left_identifiers[@]} )); then
      printf '%s\n' -1
      return 0
    fi
    if (( index >= ${#right_identifiers[@]} )); then
      printf '%s\n' 1
      return 0
    fi
    result="$(deploy_version_compare_identifier "${left_identifiers[$index]}" "${right_identifiers[$index]}")"
    [[ "$result" == 0 ]] || { printf '%s\n' "$result"; return 0; }
  done

  printf '%s\n' 0
}

deploy_version_is_newer() {
  [[ "$(deploy_version_compare "$1" "$2")" == 1 ]]
}

deploy_version_is_older() {
  [[ "$(deploy_version_compare "$1" "$2")" == -1 ]]
}

# ----- lib/operation.sh -----

DEPLOY_OPERATION_ROOT="${DEPLOY_OPERATION_ROOT:-/var/lib/deploy-scripts}"
DEPLOY_OPERATION_LOG_ROOT="${DEPLOY_OPERATION_LOG_ROOT:-/var/log/deploy-scripts}"
DEPLOY_OPERATION_LOGROTATE_FILE="${DEPLOY_OPERATION_LOGROTATE_FILE:-/etc/logrotate.d/deploy-scripts}"
DEPLOY_OPERATION_LOGROTATE_DAYS="${DEPLOY_OPERATION_LOGROTATE_DAYS:-30}"
DEPLOY_OPERATION_LOGROTATE_FILES="${DEPLOY_OPERATION_LOGROTATE_FILES:-20}"
DEPLOY_OPERATION_STATE_DIR="${DEPLOY_OPERATION_ROOT}/state"
DEPLOY_OPERATION_HISTORY_DIR="${DEPLOY_OPERATION_ROOT}/history"
DEPLOY_OPERATION_HISTORY_FILE="${DEPLOY_OPERATION_HISTORY_DIR}/operations.jsonl"

operation_is_valid_app_id() { [[ "${1:-}" =~ ^[a-z][a-z0-9_-]{0,63}$ ]]; }
operation_is_valid_scope() { case "${1:-}" in app|manager|self_update) return 0;; *) return 1;; esac; }
operation_is_valid_action() { [[ "${1:-}" =~ ^[a-z][a-z0-9_-]{0,63}$ ]]; }
operation_timestamp() { date '+%Y-%m-%dT%H:%M:%S%:z'; }
operation_run_timestamp() { date '+%Y%m%dT%H%M%S%z'; }

operation_json_escape() {
  local value="${1:-}"
  value="${value//\\/\\\\}"
  value="${value//\"/\\\"}"
  value="${value//$'\n'/\\n}"
  value="${value//$'\r'/\\r}"
  value="${value//$'\t'/\\t}"
  printf '%s' "$value"
}

operation_json_nullable() {
  if [[ -n "${1:-}" ]]; then
    printf '"%s"' "$(operation_json_escape "$1")"
  else
    printf 'null'
  fi
}

operation_safe_summary() {
  local value="${1:-}" max_bytes="${2:-512}"
  value="${value//$'\n'/ }"; value="${value//$'\r'/ }"
  value="$(printf '%s' "$value" | sed -E \
    -e 's/([[:alnum:]_.-]*(TOKEN|PASSWORD|SECRET|API_KEY|PRIVATE_KEY|KEY)[[:alnum:]_.-]*[[:space:]]*=[[:space:]]*)[^[:space:]]+/\1[REDACTED]/Ig' \
    -e 's#(Authorization:[[:space:]]*Bearer[[:space:]]+)[^[:space:]]+#\1[REDACTED]#Ig' \
    -e 's#(https?://[^:/[:space:]]+):[^@/[:space:]]+@#\1:[REDACTED]@#g')"
  (( ${#value} > max_bytes )) && value="${value:0:max_bytes}"
  printf '%s' "$value"
}

operation_redact_line() {
  local line="$1"
  printf '%s\n' "$line" | sed -E \
    -e 's/([[:alnum:]_.-]*(TOKEN|PASSWORD|SECRET|API_KEY|PRIVATE_KEY|KEY)[[:alnum:]_.-]*[[:space:]]*=[[:space:]]*)[^[:space:]]+/\1[REDACTED]/Ig' \
    -e 's#(Authorization:[[:space:]]*Bearer[[:space:]]+)[^[:space:]]+#\1[REDACTED]#Ig' \
    -e 's#(https?://[^:/[:space:]]+):[^@/[:space:]]+@#\1:[REDACTED]@#g'
}

operation_log_stream() {
  local log_path="$1" line=""
  while IFS= read -r line || [[ -n "$line" ]]; do
    printf '%s\n' "$line"
    operation_redact_line "$line" >>"$log_path"
    line=""
  done
}

operation_stream_output() {
  local log_path="$1"
  operation_log_stream "$log_path"
}

operation_stream_error() {
  local log_path="$1"
  operation_log_stream "$log_path" >&2
}

operation_discard_output_streams() {
  local output_dir="${OPERATION_OUTPUT_DIR:-}" stdout_pid="${OPERATION_STDOUT_PID:-}" stderr_pid="${OPERATION_STDERR_PID:-}" saved_stdout_fd="${OPERATION_SAVED_STDOUT_FD:-}" saved_stderr_fd="${OPERATION_SAVED_STDERR_FD:-}"
  [[ -n "$output_dir" ]] || return 0
  [[ -z "$stdout_pid" ]] || kill "$stdout_pid" 2>/dev/null || true
  [[ -z "$stderr_pid" ]] || kill "$stderr_pid" 2>/dev/null || true
  [[ -z "$stdout_pid" ]] || wait "$stdout_pid" 2>/dev/null || true
  [[ -z "$stderr_pid" ]] || wait "$stderr_pid" 2>/dev/null || true
  [[ -z "$saved_stdout_fd" ]] || eval "exec ${saved_stdout_fd}>&-" || true
  [[ -z "$saved_stderr_fd" ]] || eval "exec ${saved_stderr_fd}>&-" || true
  rm -rf -- "$output_dir"
  unset OPERATION_OUTPUT_DIR OPERATION_STDOUT_PID OPERATION_STDERR_PID OPERATION_SAVED_STDOUT_FD OPERATION_SAVED_STDERR_FD
}
operation_finish_output_streams() {
  local output_dir="${OPERATION_OUTPUT_DIR:-}" stdout_pid="${OPERATION_STDOUT_PID:-}" stderr_pid="${OPERATION_STDERR_PID:-}" saved_stdout_fd="${OPERATION_SAVED_STDOUT_FD:-}" saved_stderr_fd="${OPERATION_SAVED_STDERR_FD:-}"
  [[ -n "$output_dir" ]] || return 0
  [[ -z "$stdout_pid" ]] || wait "$stdout_pid" || true
  [[ -z "$stderr_pid" ]] || wait "$stderr_pid" || true
  [[ -z "$saved_stdout_fd" ]] || eval "exec ${saved_stdout_fd}>&-" || true
  [[ -z "$saved_stderr_fd" ]] || eval "exec ${saved_stderr_fd}>&-" || true
  rm -rf -- "$output_dir"
  unset OPERATION_OUTPUT_DIR OPERATION_STDOUT_PID OPERATION_STDERR_PID OPERATION_SAVED_STDOUT_FD OPERATION_SAVED_STDERR_FD
}

operation_set_owner_and_mode() {
  local path="$1" mode="$2"; chmod "$mode" "$path" || return 1
  if [[ "${EUID:-$(id -u)}" -eq 0 ]]; then chown root:root "$path" || return 1; fi
}
operation_write_logrotate() {
  local target="${DEPLOY_OPERATION_LOGROTATE_FILE:-}" tmp days files log_root
  [[ -n "$target" ]] || return 0
  [[ "$target" != *$'\n'* && "$target" != *$'\r'* ]] || return 1
  days="${DEPLOY_OPERATION_LOGROTATE_DAYS:-30}"
  files="${DEPLOY_OPERATION_LOGROTATE_FILES:-20}"
  [[ "$days" =~ ^[1-9][0-9]*$ && "$files" =~ ^[1-9][0-9]*$ ]] || return 1
  log_root="${DEPLOY_OPERATION_LOG_ROOT%/}"
  [[ -n "$log_root" && "$log_root" != *$'\n'* && "$log_root" != *$'\r'* ]] || return 1
  mkdir -p "$(dirname "$target")" || return 1
  tmp="$(mktemp "$(dirname "$target")/.$(basename "$target").XXXXXX")" || return 1
  if ! cat >"$tmp" <<LOGROTATE
${log_root}/*/*.log {
    daily
    rotate ${files}
    maxage ${days}
    compress
    delaycompress
    missingok
    notifempty
    create 0640 root root
}
LOGROTATE
  then
    rm -f "$tmp"
    return 1
  fi
  if ! chmod 644 "$tmp" || { [[ "${EUID:-$(id -u)}" -eq 0 ]] && ! chown root:root "$tmp"; }; then
    rm -f "$tmp"
    return 1
  fi
  mv -f "$tmp" "$target" || { rm -f "$tmp"; return 1; }
}

operation_ensure_logrotate() {
  # Framework installation owns the system policy; unprivileged dry-runs and
  # tests must not repeatedly attempt to mutate /etc.
  [[ "${EUID:-$(id -u)}" -eq 0 ]] || return 0
  operation_write_logrotate || {
    printf 'warning: unable to write operation logrotate policy: %s\n' "${DEPLOY_OPERATION_LOGROTATE_FILE:-unset}" >&2
    return 0
  }
}

operation_ensure_directories() {
  local dir
  for dir in "$DEPLOY_OPERATION_ROOT" "$DEPLOY_OPERATION_STATE_DIR" "$DEPLOY_OPERATION_HISTORY_DIR" "$DEPLOY_OPERATION_LOG_ROOT"; do
    mkdir -p "$dir" || return 1; operation_set_owner_and_mode "$dir" 750 || return 1
  done
  operation_ensure_logrotate
}
operation_state_file_for() {
  local scope="$1" app_id="${2:-}"
  case "$scope" in
    app) operation_is_valid_app_id "$app_id" || return 1; printf '%s/%s.json\n' "$DEPLOY_OPERATION_STATE_DIR" "$app_id";;
    manager) printf '%s/manager.json\n' "$DEPLOY_OPERATION_STATE_DIR";;
    self_update) printf '%s/self-update.json\n' "$DEPLOY_OPERATION_ROOT";;
    *) return 1;;
  esac
}
operation_log_path_for() {
  local scope="$1" app_id="$2" run_id="$3" directory
  case "$scope" in
    app) operation_is_valid_app_id "$app_id" || return 1; directory="${DEPLOY_OPERATION_LOG_ROOT}/${app_id}";;
    manager) directory="${DEPLOY_OPERATION_LOG_ROOT}/manager";;
    self_update) directory="${DEPLOY_OPERATION_LOG_ROOT}/self-update";;
    *) return 1;;
  esac
  mkdir -p "$directory" || return 1; operation_set_owner_and_mode "$directory" 750 || return 1
  printf '%s/%s.log\n' "$directory" "$run_id"
}
operation_new_run_id() { printf '%s-%s-%s-%04x%04x\n' "$(operation_run_timestamp)" "${2:-$1}" "$3" "$RANDOM" "$RANDOM"; }
operation_reset() { unset OPERATION_ACTIVE OPERATION_RUN_ID OPERATION_SCOPE OPERATION_APP_ID OPERATION_ACTION OPERATION_STARTED_AT OPERATION_FINISHED_AT OPERATION_STATE OPERATION_LAST_STEP OPERATION_EXIT_CODE OPERATION_ERROR_SUMMARY OPERATION_LOG_PATH OPERATION_STEPS_FILE OPERATION_CAPTURE_DIR OPERATION_OUTPUT_DIR OPERATION_STDOUT_PID OPERATION_STDERR_PID OPERATION_SAVED_STDOUT_FD OPERATION_SAVED_STDERR_FD OPERATION_PREVIOUS_EXIT_TRAP OPERATION_PREVIOUS_INT_TRAP OPERATION_PREVIOUS_TERM_TRAP OPERATION_PREVIOUS_HUP_TRAP OPERATION_INTERRUPTED_SIGNAL OPERATION_INTERRUPTION_CLEANUP_FN OPERATION_INTERRUPTION_SUMMARY; }
operation_restore_exit_trap() {
  local previous_trap="${1:-}"
  if [[ -n "$previous_trap" ]]; then
    eval "$previous_trap"
  else
    trap - EXIT
  fi
}

operation_return_status() {
  return "$1"
}

operation_restore_signal_trap() {
  local signal="$1" previous_trap="${2:-}"
  if [[ -n "$previous_trap" ]]; then
    eval "$previous_trap"
  else
    trap - "$signal"
  fi
}

operation_restore_signal_traps() {
  operation_restore_signal_trap INT "${OPERATION_PREVIOUS_INT_TRAP:-}"
  operation_restore_signal_trap TERM "${OPERATION_PREVIOUS_TERM_TRAP:-}"
  operation_restore_signal_trap HUP "${OPERATION_PREVIOUS_HUP_TRAP:-}"
}

operation_signal_exit_code() {
  case "${1:-TERM}" in
    INT) printf '130' ;;
    HUP) printf '129' ;;
    TERM) printf '143' ;;
    *) printf '1' ;;
  esac
}

operation_action_signal_trap() {
  local signal="${1:-TERM}" exit_code
  [[ -n "${OPERATION_INTERRUPTED_SIGNAL:-}" ]] && return 0
  OPERATION_INTERRUPTED_SIGNAL="$signal"
  exit_code="$(operation_signal_exit_code "$signal")"
  trap - INT TERM HUP
  exit "$exit_code"
}
operation_invoke_exit_trap() {
  local status="$1" previous_trap="${2:-}" command had_errexit=0
  [[ -n "$previous_trap" ]] || exit "$status"
  command="${previous_trap#trap -- }"
  command="${command% EXIT}"
  if [[ "$command" == "'__deploy_run_exit_handlers'" &&
        "$(type -t __deploy_run_exit_handlers 2>/dev/null || true)" == function ]]; then
    __DEPLOY_EXIT_STATUS="$status"
    __deploy_run_exit_handlers
  fi
  [[ "$-" == *e* ]] && had_errexit=1
  set +e
  # Make the original status available as `$?` to an arbitrary prior EXIT
  # trap. The status-setting function is deliberately the command immediately
  # before eval; assignments and local declarations would otherwise erase it.
  operation_return_status "$status"
  eval "$command"
  (( had_errexit == 1 )) && set -e
  exit "$status"
}

operation_steps_json() {
  local first=1 name state started_at finished_at; printf '['
  while IFS=$'\t' read -r name state started_at finished_at; do
    [[ -n "$name" ]] || continue; [[ "$first" -eq 1 ]] || printf ','; first=0
    printf '{"name":"%s","state":"%s","started_at":"%s","finished_at":%s}' "$(operation_json_escape "$name")" "$(operation_json_escape "$state")" "$(operation_json_escape "$started_at")" "$(operation_json_nullable "$finished_at")"
  done < "$OPERATION_STEPS_FILE"; printf ']'
}
operation_write_record() {
  [[ "${OPERATION_ACTIVE:-0}" == 1 ]] || return 1
  local state_file tmp_file app_json=null finished_json=null error_json=null steps_json='[]' last_step_json=null
  state_file="$(operation_state_file_for "$OPERATION_SCOPE" "${OPERATION_APP_ID:-}")" || return 1
  [[ -n "${OPERATION_APP_ID:-}" ]] && app_json="\"$(operation_json_escape "$OPERATION_APP_ID")\""
  [[ -n "${OPERATION_FINISHED_AT:-}" ]] && finished_json="\"$(operation_json_escape "$OPERATION_FINISHED_AT")\""
  [[ -n "${OPERATION_ERROR_SUMMARY:-}" ]] && error_json="\"$(operation_json_escape "$OPERATION_ERROR_SUMMARY")\""
  [[ -n "${OPERATION_LAST_STEP:-}" ]] && last_step_json="\"$(operation_json_escape "$OPERATION_LAST_STEP")\""
  [[ -f "${OPERATION_STEPS_FILE:-}" ]] && steps_json="$(operation_steps_json)"
  tmp_file="$(mktemp "${state_file}.tmp.XXXXXX")" || return 1
  printf '{"schema_version":1,"run_id":"%s","scope":"%s","app_id":%s,"action":"%s","state":"%s","started_at":"%s","finished_at":%s,"last_step":%s,"steps":%s,"exit_code":%s,"error":%s,"log_path":"%s"}\n' "$(operation_json_escape "$OPERATION_RUN_ID")" "$(operation_json_escape "$OPERATION_SCOPE")" "$app_json" "$(operation_json_escape "$OPERATION_ACTION")" "$(operation_json_escape "$OPERATION_STATE")" "$(operation_json_escape "$OPERATION_STARTED_AT")" "$finished_json" "$last_step_json" "$steps_json" "${OPERATION_EXIT_CODE:-null}" "$error_json" "$(operation_json_escape "$OPERATION_LOG_PATH")" > "$tmp_file" || { rm -f "$tmp_file"; return 1; }
  operation_set_owner_and_mode "$tmp_file" 640 || { rm -f "$tmp_file"; return 1; }; mv -f "$tmp_file" "$state_file" || { rm -f "$tmp_file"; return 1; }
}
operation_append_history() { local state_file; state_file="$(operation_state_file_for "$OPERATION_SCOPE" "${OPERATION_APP_ID:-}")" || return 1; [[ -f "$state_file" ]] || return 1; cat "$state_file" >> "$DEPLOY_OPERATION_HISTORY_FILE" || return 1; operation_set_owner_and_mode "$DEPLOY_OPERATION_HISTORY_FILE" 640; }
operation_start() {
  local scope="$1" app_id="$2" action="$3"
  operation_is_valid_scope "$scope" || return 2
  operation_is_valid_action "$action" || return 2
  [[ "$scope" != app || -n "$app_id" ]] || return 2
  [[ "$scope" != app ]] || operation_is_valid_app_id "$app_id" || return 2
  operation_ensure_directories || return 1
  operation_reset

  OPERATION_ACTIVE=1
  OPERATION_SCOPE="$scope"
  OPERATION_APP_ID="$app_id"
  OPERATION_ACTION="$action"
  OPERATION_RUN_ID="$(operation_new_run_id "$scope" "$app_id" "$action")"
  OPERATION_STARTED_AT="$(operation_timestamp)"
  OPERATION_STATE=running
  OPERATION_LOG_PATH="$(operation_log_path_for "$scope" "$app_id" "$OPERATION_RUN_ID")" || { operation_reset; return 1; }
  OPERATION_STEPS_FILE="$(mktemp "${DEPLOY_OPERATION_ROOT}/.operation-steps.XXXXXX")" || { operation_reset; return 1; }
  operation_set_owner_and_mode "$OPERATION_STEPS_FILE" 600 || { rm -f "$OPERATION_STEPS_FILE"; operation_reset; return 1; }
  : > "$OPERATION_LOG_PATH" || { rm -f "$OPERATION_STEPS_FILE"; operation_reset; return 1; }
  operation_set_owner_and_mode "$OPERATION_LOG_PATH" 640 || { rm -f "$OPERATION_STEPS_FILE"; operation_reset; return 1; }
  operation_write_record || { rm -f "$OPERATION_STEPS_FILE"; operation_reset; return 1; }
}
operation_step_start() { local name="$1" now updated; [[ "${OPERATION_ACTIVE:-0}" == 1 && "$name" =~ ^[a-z][a-z0-9_-]{0,63}$ ]] || return 1; now="$(operation_timestamp)"; updated="$(mktemp "${OPERATION_STEPS_FILE}.XXXXXX")" || return 1; awk -F '\t' -v name="$name" '$1 != name { print }' "$OPERATION_STEPS_FILE" > "$updated" || return 1; printf '%s\trunning\t%s\t\n' "$name" "$now" >> "$updated"; mv -f "$updated" "$OPERATION_STEPS_FILE"; OPERATION_LAST_STEP="$name"; operation_write_record; }
operation_step_finish() { local name="$1" state="${2:-succeeded}" now updated found=0 step_name step_state started_at finished_at; [[ "${OPERATION_ACTIVE:-0}" == 1 ]] || return 1; case "$state" in succeeded|failed|skipped) ;; *) return 2;; esac; now="$(operation_timestamp)"; updated="$(mktemp "${OPERATION_STEPS_FILE}.XXXXXX")" || return 1; while IFS=$'\t' read -r step_name step_state started_at finished_at; do [[ -n "$step_name" ]] || continue; if [[ "$step_name" == "$name" ]]; then printf '%s\t%s\t%s\t%s\n' "$name" "$state" "$started_at" "$now" >> "$updated"; found=1; else printf '%s\t%s\t%s\t%s\n' "$step_name" "$step_state" "$started_at" "$finished_at" >> "$updated"; fi; done < "$OPERATION_STEPS_FILE"; [[ "$found" -eq 1 ]] || { rm -f "$updated"; return 1; }; mv -f "$updated" "$OPERATION_STEPS_FILE"; OPERATION_LAST_STEP="$name"; operation_write_record; }
operation_finish() { local exit_code="${1:-1}" state="${2:-}" summary="${3:-}"; [[ "${OPERATION_ACTIVE:-0}" == 1 && "$exit_code" =~ ^[0-9]+$ ]] || return 1; [[ -n "$state" ]] || { [[ "$exit_code" -eq 0 ]] && state=succeeded || state=failed; }; case "$state" in succeeded|failed|cancelled|interrupted|rolled_back|rollback_failed) ;; *) return 2;; esac; OPERATION_STATE="$state"; OPERATION_EXIT_CODE="$exit_code"; OPERATION_FINISHED_AT="$(operation_timestamp)"; OPERATION_ERROR_SUMMARY="$(operation_safe_summary "$summary")"; operation_write_record || return 1; operation_append_history || return 1; rm -f "$OPERATION_STEPS_FILE"; operation_reset; }
operation_action_exit_trap() {
  local status="$?" action="${OPERATION_ACTION:-unknown}" previous_trap="${OPERATION_PREVIOUS_EXIT_TRAP:-}"
  if [[ -n "${OPERATION_SAVED_STDOUT_FD:-}" ]]; then
    eval "exec 1>&${OPERATION_SAVED_STDOUT_FD} 2>&${OPERATION_SAVED_STDERR_FD}" || true
  fi
  trap - EXIT
  if [[ "${OPERATION_ACTIVE:-0}" == 1 ]]; then
    operation_restore_signal_traps || true
    if [[ -n "${OPERATION_INTERRUPTED_SIGNAL:-}" && -n "${OPERATION_INTERRUPTION_CLEANUP_FN:-}" ]] \
      && declare -f "${OPERATION_INTERRUPTION_CLEANUP_FN}" >/dev/null 2>&1; then
      "${OPERATION_INTERRUPTION_CLEANUP_FN}" "$status" || true
    fi
    if [[ -n "${OPERATION_INTERRUPTED_SIGNAL:-}" ]]; then
      operation_discard_output_streams || true
    else
      operation_finish_output_streams || true
    fi
    if [[ "$status" -eq 0 ]]; then
      operation_step_finish execute succeeded || true
    else
      operation_step_finish execute failed || true
    fi
    if [[ -n "${OPERATION_INTERRUPTED_SIGNAL:-}" ]]; then
      operation_finish "$status" interrupted "${OPERATION_INTERRUPTION_SUMMARY:-${action} interrupted by SIG${OPERATION_INTERRUPTED_SIGNAL}}" || true
    else
      operation_finish "$status" "" "${action} exited with status ${status}" || true
    fi
  fi
  operation_invoke_exit_trap "$status" "$previous_trap"
}

operation_run_app_action() {
  local action="$1" function_name="$2" status output_dir log_path
  operation_is_valid_action "$action" || return 2
  [[ "$function_name" =~ ^[a-zA-Z_][a-zA-Z0-9_]*$ ]] || return 2
  declare -f "$function_name" >/dev/null 2>&1 || return 2
  # A non-root invocation cannot create the framework's root-owned operation
  # paths. Let the action's own root guard produce the established, actionable
  # error instead of masking it with an operation-record setup failure.
  if [[ "${EUID:-$(id -u)}" -ne 0 &&
        "${DEPLOY_OPERATION_ROOT:-/var/lib/deploy-scripts}" == /var/lib/deploy-scripts &&
        "${DEPLOY_OPERATION_LOG_ROOT:-/var/log/deploy-scripts}" == /var/log/deploy-scripts ]]; then
    "$function_name"
    return $?
  fi
  operation_start app "${APP_ID:-}" "$action" || error "Unable to start operation record for ${APP_NAME:-app} ${action}"
  if ! operation_step_start execute; then
    operation_finish 1 failed "failed to start execute step" || true
    error "Unable to record operation step for ${APP_NAME:-app} ${action}"
  fi
  local previous_trap previous_int_trap previous_term_trap previous_hup_trap
  previous_trap="$(trap -p EXIT)"
  previous_int_trap="$(trap -p INT)"
  previous_term_trap="$(trap -p TERM)"
  previous_hup_trap="$(trap -p HUP)"
  OPERATION_PREVIOUS_EXIT_TRAP="$previous_trap"
  OPERATION_PREVIOUS_INT_TRAP="$previous_int_trap"
  OPERATION_PREVIOUS_TERM_TRAP="$previous_term_trap"
  OPERATION_PREVIOUS_HUP_TRAP="$previous_hup_trap"
  trap 'operation_action_exit_trap' EXIT
  trap 'operation_action_signal_trap INT' INT
  trap 'operation_action_signal_trap TERM' TERM
  trap 'operation_action_signal_trap HUP' HUP
  log_path="$OPERATION_LOG_PATH"
  output_dir="$(mktemp -d "${TMPDIR:-/tmp}/deploy-operation-output.XXXXXX")" || {
    operation_restore_exit_trap "$previous_trap" || true
    operation_finish 1 failed 'failed to create operation output directory' || true
    return 1
  }
  chmod 700 "$output_dir" || {
    rm -rf -- "$output_dir"
    operation_restore_exit_trap "$previous_trap" || true
    operation_finish 1 failed 'failed to secure operation output directory' || true
    return 1
  }
  command -v mkfifo >/dev/null 2>&1 || {
    rm -rf -- "$output_dir"
    operation_restore_exit_trap "$previous_trap" || true
    operation_finish 1 failed 'mkfifo is required for operation logging' || true
    return 1
  }
  mkfifo "${output_dir}/stdout" "${output_dir}/stderr" || {
    rm -rf -- "$output_dir"
    operation_restore_exit_trap "$previous_trap" || true
    operation_finish 1 failed 'failed to create operation output pipes' || true
    return 1
  }
  OPERATION_OUTPUT_DIR="$output_dir"
  ( trap - EXIT; operation_stream_output "$log_path" <"${output_dir}/stdout" ) &
  OPERATION_STDOUT_PID=$!
  ( trap - EXIT; operation_stream_error "$log_path" <"${output_dir}/stderr" ) &
  OPERATION_STDERR_PID=$!
  # Readers are open before the action starts, so its output remains visible
  # immediately while a separately redacted copy is appended to the log.
  exec {OPERATION_SAVED_STDOUT_FD}>&1
  exec {OPERATION_SAVED_STDERR_FD}>&2
  # Keep the action in the current shell so application functions retain
  # their normal shell semantics. The wrapper EXIT trap records an explicit
  # `exit`, errexit termination, and ordinary non-zero returns alike.
  "$function_name" >"${output_dir}/stdout" 2>"${output_dir}/stderr"
  status=$?
  operation_finish_output_streams || true
  operation_restore_signal_traps || true
  operation_restore_exit_trap "$previous_trap" || true
  if [[ "$status" -eq 0 ]]; then
    operation_step_finish execute succeeded || operation_finish 1 failed "failed to finish execute step"
    operation_finish 0 || return 1
  else
    operation_step_finish execute failed || true
    operation_finish "$status" "" "${action} exited with status ${status}" || true
  fi
  return "$status"
}

# ----- lib/state.sh -----

DEPLOY_STATE_SCHEMA_VERSION=2
DEPLOY_STATUS_NO_PROBE="${DEPLOY_STATUS_NO_PROBE:-0}"
DEPLOY_STATUS_NO_NETWORK="${DEPLOY_STATUS_NO_NETWORK:-0}"
DEPLOY_STATUS_TIMEOUT_SECONDS="${DEPLOY_STATUS_TIMEOUT_SECONDS:-8}"

state_now() { date '+%Y-%m-%dT%H:%M:%S%:z'; }
state_json_nullable() { [[ -n "${1:-}" && "${1:-}" != null ]] && app_json_string "$1" || printf 'null'; }

# Parse one scalar or object member from JSON emitted by this framework. This is
# deliberately small, but handles escaped strings and nested objects without
# relying on jq or Python at runtime.
state_json_unescape() {
  local value="${1:-}" result='' i c next hex code char backslash=\\
  for ((i = 0; i < ${#value}; i++)); do
    c="${value:i:1}"
    if [[ "$c" != "$backslash" ]]; then
      result+="$c"
      continue
    fi
    i=$((i + 1))
    [[ $i -lt ${#value} ]] || return 1
    next="${value:i:1}"
    case "$next" in
      '"') result+='"' ;;
      "$backslash") result+="$backslash" ;;
      '/') result+='/' ;;
      b) result+=$'\b' ;;
      f) result+=$'\f' ;;
      n) result+=$'\n' ;;
      r) result+=$'\r' ;;
      t) result+=$'\t' ;;
      u)
        hex="${value:i+1:4}"
        [[ "$hex" =~ ^[0-9a-fA-F]{4}$ ]] || return 1
        [[ "${hex:0:2}" == 00 ]] || return 1
        code=$((16#${hex:2:2}))
        printf -v char '%b' "\\$(printf '%03o' "$code")"
        result+="$char"
        i=$((i + 4))
        ;;
      *) return 1 ;;
    esac
  done
  printf '%s' "$result"
}

state_json_scan_value() {
  local json="$1" start="$2" len=${#1} i c depth quote escaped
  while [[ $start -lt $len && "${json:start:1}" =~ [[:space:]] ]]; do start=$((start + 1)); done
  [[ $start -lt $len ]] || return 1
  c="${json:start:1}"
  if [[ "$c" == '"' ]]; then
    i=$((start + 1)); escaped=0
    while [[ $i -lt $len ]]; do
      c="${json:i:1}"
      if (( escaped )); then escaped=0
      elif [[ "$c" == \\ ]]; then escaped=1
      elif [[ "$c" == '"' ]]; then
        STATE_JSON_VALUE_RAW="${json:start:i-start+1}"
        STATE_JSON_VALUE_END=$((i + 1))
        return 0
      fi
      i=$((i + 1))
    done
    return 1
  fi
  if [[ "$c" == '{' || "$c" == '[' ]]; then
    depth=0; quote=0; escaped=0
    for ((i = start; i < len; i++)); do
      c="${json:i:1}"
      if (( quote )); then
        if (( escaped )); then escaped=0
        elif [[ "$c" == \\ ]]; then escaped=1
        elif [[ "$c" == '"' ]]; then quote=0
        fi
        continue
      fi
      if [[ "$c" == '"' ]]; then quote=1; continue; fi
      [[ "$c" == '{' || "$c" == '[' ]] && depth=$((depth + 1))
      if [[ "$c" == '}' || "$c" == ']' ]]; then
        depth=$((depth - 1))
        if (( depth == 0 )); then
          STATE_JSON_VALUE_RAW="${json:start:i-start+1}"
          STATE_JSON_VALUE_END=$((i + 1))
          return 0
        fi
      fi
    done
    return 1
  fi
  i=$start
  while [[ $i -lt $len && "${json:i:1}" != ',' && "${json:i:1}" != '}' && "${json:i:1}" != ']' ]]; do i=$((i + 1)); done
  STATE_JSON_VALUE_RAW="${json:start:i-start}"; STATE_JSON_VALUE_RAW="${STATE_JSON_VALUE_RAW%%[[:space:]]}"
  STATE_JSON_VALUE_END=$i
  [[ -n "$STATE_JSON_VALUE_RAW" ]]
}

state_json_raw_field() {
  local json="$1" key="$2" len=${#1} i=0 c token token_raw value_end
  while ((i < len)); do
    c="${json:i:1}"
    if [[ "$c" != '"' ]]; then i=$((i + 1)); continue; fi
    token_raw=''; i=$((i + 1))
    while ((i < len)); do
      c="${json:i:1}"
      if [[ "$c" == \\ ]]; then
        token_raw+="$c"; i=$((i + 1)); [[ $i -lt $len ]] || return 1; token_raw+="${json:i:1}"; i=$((i + 1)); continue
      fi
      [[ "$c" == '"' ]] && break
      token_raw+="$c"; i=$((i + 1))
    done
    [[ $i -lt $len && "${json:i:1}" == '"' ]] || return 1
    token="$(state_json_unescape "$token_raw")" || return 1
    i=$((i + 1))
    while [[ $i -lt $len && "${json:i:1}" =~ [[:space:]] ]]; do i=$((i + 1)); done
    [[ $i -lt $len && "${json:i:1}" == ':' ]] || continue
    i=$((i + 1))
    state_json_scan_value "$json" "$i" || return 1
    value_end=$STATE_JSON_VALUE_END
    if [[ "$token" == "$key" ]]; then
      printf '%s' "$STATE_JSON_VALUE_RAW"
      return 0
    fi
    i=$value_end
  done
  return 1
}

state_json_field() {
  local object="$1" path="$2" section raw
  if [[ "$path" == *.* ]]; then
    section="${path%%.*}"
    raw="$(state_json_raw_field "$object" "$section")" || return 1
    [[ "$raw" == \{*\} ]] || return 1
    state_json_field "$raw" "${path#*.}"
    return
  fi
  raw="$(state_json_raw_field "$object" "$path")" || return 1
  case "$raw" in
    null) printf 'null\n' ;;
    true|false) printf '%s\n' "$raw" ;;
    '"'*) state_json_unescape "${raw:1:${#raw}-2}"; printf '\n' ;;
    *) printf '%s\n' "$raw" ;;
  esac
}

state_json_object_field() { state_json_field "$1" "$2"; }
state_object_field() { state_json_field "$1" "$2"; }

state_operation_record() {
  local app_id="$1" file
  operation_is_valid_app_id "$app_id" || return 1
  file="$(operation_state_file_for app "$app_id")" || return 1
  [[ -f "$file" ]] || return 1
  cat "$file"
}

state_operation_field() {
  local app_id="$1" key="$2" object
  object="$(state_operation_record "$app_id")" || return 1
  state_json_field "$object" "$key"
}

state_service_object() {
  local name="$1" unit_exists=null active=null enabled=null state=unknown
  if ! command -v systemctl >/dev/null 2>&1; then
    state=unknown
  elif systemctl list-unit-files "${name}.service" --no-legend --no-pager 2>/dev/null | grep -q .; then
    unit_exists=true
    systemctl is-active --quiet "$name" 2>/dev/null && active=true || active=false
    systemctl is-enabled --quiet "$name" 2>/dev/null && enabled=true || enabled=false
    if [[ "$active" == true ]]; then state=running
    elif systemctl is-failed --quiet "$name" 2>/dev/null; then state=failed
    elif [[ "$enabled" == false ]]; then state=disabled
    else state=stopped
    fi
  else
    unit_exists=false; state=not_found
  fi
  printf '{"name":%s,"unit_exists":%s,"active":%s,"enabled":%s,"state":%s}' \
    "$(app_json_string "$name")" "$(app_json_value "$unit_exists")" \
    "$(app_json_value "$active")" "$(app_json_value "$enabled")" "$(app_json_string "$state")"
}

state_service_names() {
  local primary name
  if primary="$(app_doctor_service_name 2>/dev/null)"; then printf '%s\n' "$primary"; fi
  if [[ -n "${APP_DOCTOR_SERVICES_FN:-}" ]] && declare -f "$APP_DOCTOR_SERVICES_FN" >/dev/null 2>&1; then
    while IFS= read -r name; do
      [[ -n "$name" && "$name" != "${primary:-}" ]] && printf '%s\n' "$name"
    done < <("$APP_DOCTOR_SERVICES_FN" 2>/dev/null || true)
  fi
}

state_service_aggregate() {
  local state name found=0 has_failed=0 has_nonrunning=0 has_unknown=0
  while IFS= read -r name; do
    [[ -n "$name" ]] || continue
    found=1
    local service_json; service_json="$(state_service_object "$name")"; state="$(state_json_field "$service_json" state 2>/dev/null || true)"
    case "$state" in
      failed) has_failed=1 ;;
      running) ;;
      stopped|disabled|not_found) has_nonrunning=1 ;;
      *) has_unknown=1 ;;
    esac
  done < <(state_service_names)
  if (( ! found )); then printf '%s\n' not_managed
  elif (( has_failed )); then printf '%s\n' failed
  elif (( has_nonrunning )); then printf '%s\n' stopped
  elif (( has_unknown )); then printf '%s\n' unknown
  else printf '%s\n' running
  fi
}

state_health_url_is_local() {
  local url="$1" host
  host="${url#*://}"; host="${host%%/*}"; host="${host%%:*}"
  [[ "$host" == 127.0.0.1 || "$host" == localhost || "$host" == ::1 || "$host" == \[::1\] ]]
}

state_health_json() {
  local install_state="${1:-unknown}" service_state="${2:-unknown}" checked code output
  if [[ "$install_state" == not_installed || "$install_state" == install_failed || "$install_state" == uninstalling ]]; then
    printf '{"state":"unsupported","checked_at":null,"probe_type":null,"url":null,"http_code":null,"message":null}'
    return
  fi
  if [[ "$service_state" != running && -n "${BA_HEALTH_URL:-}" && -z "${APP_STATUS_HEALTH_FN:-}" ]]; then
    printf '{"state":"not_checked","checked_at":null,"probe_type":null,"url":%s,"http_code":null,"message":"service is not running"}' "$(app_json_string "$BA_HEALTH_URL")"
    return
  fi
  if [[ "$DEPLOY_STATUS_NO_PROBE" == 1 ]]; then
    printf '{"state":"not_checked","checked_at":null,"probe_type":null,"url":null,"http_code":null,"message":null}'
  elif [[ -n "${APP_STATUS_HEALTH_FN:-}" ]] && declare -f "$APP_STATUS_HEALTH_FN" >/dev/null 2>&1; then
    output="$("$APP_STATUS_HEALTH_FN" 2>/dev/null || true)"
    [[ "$(printf '%s\n' "$output" | wc -l)" -eq 1 && "$output" == \{*\} ]] || { printf '{"state":"unknown","checked_at":null,"probe_type":null,"url":null,"http_code":null,"message":"health probe returned invalid JSON"}'; return; }
    case "$(state_json_field "$output" state 2>/dev/null || true)" in healthy|degraded|unhealthy|not_checked|unsupported|unknown) printf '%s' "$output" ;; *) printf '{"state":"unknown","checked_at":null,"probe_type":null,"url":null,"http_code":null,"message":"health probe returned invalid state"}' ;; esac
  elif [[ -n "${BA_HEALTH_URL:-}" ]] && command -v curl >/dev/null 2>&1 && { [[ "$DEPLOY_STATUS_NO_NETWORK" != 1 ]] || state_health_url_is_local "$BA_HEALTH_URL"; }; then
    checked="$(state_now)"
    code="$(curl -sS -L --max-time "${DEPLOY_STATUS_HEALTH_TIMEOUT_SECONDS:-5}" -o /dev/null -w '%{http_code}' "$BA_HEALTH_URL" 2>/dev/null || printf 000)"
    if [[ "$code" =~ ^(2[0-9][0-9]|3[0-9][0-9])$ ]]; then
      printf '{"state":"healthy","checked_at":%s,"probe_type":"http","url":%s,"http_code":%s,"message":null}' "$(app_json_string "$checked")" "$(app_json_string "$BA_HEALTH_URL")" "$code"
    else
      printf '{"state":"unhealthy","checked_at":%s,"probe_type":"http","url":%s,"http_code":%s,"message":"HTTP health probe failed"}' "$(app_json_string "$checked")" "$(app_json_string "$BA_HEALTH_URL")" "$code"
    fi
  else
    printf '{"state":"not_checked","checked_at":null,"probe_type":null,"url":null,"http_code":null,"message":null}'
  fi
}

state_backup_json() {
  local install_state="${1:-unknown}" output
  if [[ "$install_state" == not_installed || "$install_state" == install_failed || "$install_state" == uninstalling ]]; then
    printf '{"state":"unsupported","last_success_at":null,"path":null,"message":null}'
    return
  fi
  if [[ -n "${APP_STATUS_BACKUP_FN:-}" ]] && declare -f "$APP_STATUS_BACKUP_FN" >/dev/null 2>&1; then
    output="$("$APP_STATUS_BACKUP_FN" 2>/dev/null || true)"
    if [[ "$(printf '%s\n' "$output" | wc -l)" -eq 1 && "$output" == \{*\} ]]; then
      case "$(state_json_field "$output" state 2>/dev/null || true)" in
        available|missing|failed|not_checked|unsupported|unknown) printf '%s' "$output"; return ;;
      esac
    fi
    printf '{"state":"unknown","last_success_at":null,"path":null,"message":"backup status returned invalid JSON"}'
    return
  fi
  printf '{"state":"unsupported","last_success_at":null,"path":null,"message":null}'
}

state_version_json() {
  local conf_file="$1" installed latest=null checked_at=null update_state=unknown source=config output
  installed="$(app_config_installed_version "$conf_file" 2>/dev/null || true)"
  [[ -n "$installed" ]] && installed="$(app_json_string "$installed")" || installed=null
  if [[ -n "${APP_STATUS_VERSION_FN:-}" ]] && declare -f "$APP_STATUS_VERSION_FN" >/dev/null 2>&1; then
    output="$("$APP_STATUS_VERSION_FN" 2>/dev/null || true)"
    if [[ "$(printf '%s\n' "$output" | wc -l)" -eq 1 && "$output" == \{*\} && -n "$(state_json_field "$output" installed 2>/dev/null || true)" ]]; then
      printf '%s' "$output"; return
    fi
  fi
  # BA_BIN_NAME is set only by implementations using the shared binary-app
  # lifecycle. Do not infer support from GITHUB_REPO alone: several custom
  # applications use GitHub for a non-comparable source/update workflow.
  if [[ -n "${BA_BIN_NAME:-}" ]] && declare -f bapp_status_version_json >/dev/null 2>&1; then
    output="$(bapp_status_version_json 2>/dev/null || true)"
    if [[ "$(printf '%s\n' "$output" | wc -l)" -eq 1 && "$output" == \{*\} && -n "$(state_json_field "$output" installed 2>/dev/null || true)" ]]; then
      printf '%s' "$output"; return
    fi
  fi
  printf '{"installed":%s,"latest":%s,"checked_at":%s,"update_state":%s,"source":%s}' "$installed" "$latest" "$checked_at" "$(app_json_string "$update_state")" "$(app_json_string "$source")"
}

state_severity() {
  local install="$1" safe="$2" valid="$3" service="$4" health="$5" update="$6" enabled="$7" backup="${8:-unsupported}"
  [[ "$safe" == false || "$valid" == false ]] && { printf critical; return; }
  [[ "$install" == unknown ]] && { printf unknown; return; }
  [[ "$install" == not_installed ]] && { printf info; return; }
  [[ "$service" == failed || "$service" == stopped || "$health" == unhealthy ]] && { printf error; return; }
  [[ "$health" == degraded || "$enabled" == false || "$update" == update_available || "$update" == stale || "$backup" == missing || "$backup" == failed || "$backup" == not_checked || "$backup" == unknown ]] && { printf warning; return; }
  printf ok
}

app_status_collect_json() {
  local conf_file config_exists=false config_safe=null config_valid=null owner=null mode=null
  local install_state=not_installed service_name="" service_state=not_managed service_enabled=null
  local health_json version_json backup_json services_json='[]' operation_state=idle
  local last_action="" last_result="" last_started="" last_finished="" last_step="" last_error_summary="" last_log_path="" last_error_code_json=null health_state="" update_state="" backup_state="" severity="" version_installed_json=""
  conf_file="$(app_conf_file)"
  if [[ -f "$conf_file" ]]; then
    config_exists=true; config_safe=true; install_state=installed
    if command -v stat >/dev/null 2>&1; then
      owner="$(stat -c '%U' "$conf_file" 2>/dev/null || printf unknown)"; mode="$(stat -c '%a' "$conf_file" 2>/dev/null || printf unknown)"
      [[ "$owner" == root && ( "$mode" == 600 || "$mode" == 400 ) ]] || config_safe=false
    fi
    if [[ "$config_safe" == true ]]; then app_doctor_validate_saved_config "$conf_file" >/dev/null 2>&1 && config_valid=true || config_valid=false; fi
  fi
  local service_unit_exists=null service_active=null service_systemctl=false
  if service_name="$(app_doctor_service_name 2>/dev/null)"; then
    service_state="$(state_service_aggregate)"
    local obj; obj="$(state_service_object "$service_name")"
    service_unit_exists="$(state_object_field "$obj" unit_exists || true)"
    service_active="$(state_object_field "$obj" active || true)"
    service_enabled="$(state_object_field "$obj" enabled || true)"
    command -v systemctl >/dev/null 2>&1 && service_systemctl=true
  fi
  health_json="$(state_health_json "$install_state" "$service_state" 2>/dev/null || printf '{"state":"unknown","checked_at":null,"probe_type":null,"url":null,"http_code":null,"message":"collection failed"}')"
  version_json="$(state_version_json "$conf_file")"
  backup_json="$(state_backup_json "$install_state")"
  if [[ -n "${APP_DOCTOR_SERVICES_FN:-}" ]] && declare -f "$APP_DOCTOR_SERVICES_FN" >/dev/null 2>&1; then
    local name first=1; services_json='['
    while IFS= read -r name; do [[ -n "$name" ]] || continue; (( first )) || services_json+=','; first=0; services_json+="$(state_service_object "$name")"; done < <("$APP_DOCTOR_SERVICES_FN" 2>/dev/null || true)
    services_json+=']'
  fi
  if [[ -n "${APP_ID:-}" ]]; then
    local operation_json=""
    operation_json="$(state_operation_record "$APP_ID" 2>/dev/null || true)"
    if [[ -n "$operation_json" ]]; then
      last_action="$(state_json_field "$operation_json" action || true)"; last_result="$(state_json_field "$operation_json" state || true)"; last_started="$(state_json_field "$operation_json" started_at || true)"; last_finished="$(state_json_field "$operation_json" finished_at || true)"; last_step="$(state_json_field "$operation_json" last_step || true)"; last_error_summary="$(state_json_field "$operation_json" error || true)"; last_log_path="$(state_json_field "$operation_json" log_path || true)"
      local operation_exit_code=""
      operation_exit_code="$(state_json_raw_field "$operation_json" exit_code 2>/dev/null || true)"
      if [[ "$operation_exit_code" =~ ^[1-9][0-9]*$ ]]; then
        last_error_code_json="$operation_exit_code"
      fi
    fi
    [[ "$last_result" == running ]] && operation_state=running
    if [[ "$last_result" == failed ]]; then
      case "$last_action" in
        install) [[ "$install_state" == not_installed ]] && install_state=install_failed ;;
        uninstall) install_state=uninstall_failed ;;
      esac
    elif [[ "$last_result" == running ]]; then
      case "$last_action" in
        install) install_state=installing ;;
        uninstall) install_state=uninstalling ;;
      esac
    fi
  fi
  health_state="$(state_json_field "$health_json" state 2>/dev/null || printf unknown)"
  update_state="$(state_json_field "$version_json" update_state 2>/dev/null || printf unknown)"
  backup_state="$(state_json_field "$backup_json" state 2>/dev/null || printf unknown)"
  severity="$(state_severity "$install_state" "$config_safe" "$config_valid" "$service_state" "$health_state" "$update_state" "$service_enabled" "$backup_state")"
  version_installed_json="$(state_json_raw_field "$version_json" installed 2>/dev/null || true)"
  [[ -n "$version_installed_json" ]] || version_installed_json=null
  printf '{"schema_version":%s,"collected_at":%s,"app_id":%s,"app_name":%s,"root":%s,"install_state":%s,"severity":%s,"config":{"path":%s,"exists":%s,"owner":%s,"mode":%s,"safe":%s,"valid":%s},"version":%s,"version_info":%s,"service":{"name":%s,"systemctl_available":%s,"unit_exists":%s,"active":%s,"enabled":%s,"state":%s},"services":%s,"health":%s,"backup":%s,"operation":{"state":%s,"last_action":%s,"last_result":%s,"last_started_at":%s,"last_finished_at":%s,"last_step":%s,"last_error_code":%s,"last_error_summary":%s,"log_path":%s}}\n' "$DEPLOY_STATE_SCHEMA_VERSION" "$(app_json_string "$(state_now)")" "$(app_json_string "${APP_ID:-}")" "$(app_json_string "${APP_NAME:-}")" "$(app_json_bool "$([[ ${EUID:-$(id -u)} -eq 0 ]] && printf true || printf false)")" "$(app_json_string "$install_state")" "$(app_json_string "$severity")" "$(app_json_string "$conf_file")" "$(app_json_bool "$config_exists")" "$(app_json_value "$owner")" "$(app_json_value "$mode")" "$(app_json_value "$config_safe")" "$(app_json_value "$config_valid")" "$version_installed_json" "$version_json" "$(state_json_nullable "$service_name")" "$(app_json_bool "$service_systemctl")" "$(app_json_value "$service_unit_exists")" "$(app_json_value "$service_active")" "$(app_json_value "$service_enabled")" "$(app_json_string "$service_state")" "$services_json" "$health_json" "$backup_json" "$(app_json_string "$operation_state")" "$(state_json_nullable "$last_action")" "$(state_json_nullable "$last_result")" "$(state_json_nullable "$last_started")" "$(state_json_nullable "$last_finished")" "$(state_json_nullable "$last_step")" "$last_error_code_json" "$(state_json_nullable "$last_error_summary")" "$(state_json_nullable "$last_log_path")"
}






# ----- lib/version_check.sh -----

# Shared, read-only GitHub-release version checking with a small on-disk cache.
# Status collection consumes this cache but never calls the network; only the
# central check-update command refreshes expired entries (or all entries with
# --refresh).
DEPLOY_VERSION_CACHE_ROOT="${DEPLOY_VERSION_CACHE_ROOT:-/var/lib/deploy-scripts/version-cache}"
DEPLOY_VERSION_CACHE_TTL_SECONDS="${DEPLOY_VERSION_CACHE_TTL_SECONDS:-21600}"
DEPLOY_VERSION_CACHE_SCHEMA_VERSION=1

version_check_now_epoch() {
  local now="${DEPLOY_VERSION_NOW_EPOCH:-}"
  if [[ "$now" =~ ^[0-9]+$ ]]; then
    printf '%s\n' "$now"
  else
    date +%s
  fi
}

version_check_timestamp_for_epoch() {
  local epoch="$1"
  if date -u -d "@${epoch}" '+%Y-%m-%dT%H:%M:%SZ' 2>/dev/null; then
    return 0
  fi
  state_now
}

version_cache_file_for() {
  local app_id="$1"
  [[ "$app_id" =~ ^[a-z][a-z0-9_-]{0,63}$ ]] || return 2
  printf '%s/%s.json\n' "${DEPLOY_VERSION_CACHE_ROOT%/}" "$app_id"
}

version_cache_ensure_directory() {
  [[ -n "${DEPLOY_VERSION_CACHE_ROOT:-}" && "${DEPLOY_VERSION_CACHE_ROOT}" = /* ]] || return 1
  [[ ! -L "$DEPLOY_VERSION_CACHE_ROOT" ]] || return 1
  mkdir -p "$DEPLOY_VERSION_CACHE_ROOT" || return 1
  chmod 700 "$DEPLOY_VERSION_CACHE_ROOT" || return 1
}

version_cache_file_is_safe() {
  local file="$1" mode
  [[ -f "$file" && ! -L "$file" ]] || return 1
  if command -v stat >/dev/null 2>&1; then
    # Git Bash translates Windows ACLs to synthetic POSIX modes, so a file
    # successfully chmodded to 0600 can still be reported as 0644. Linux
    # deployments retain the strict group/other-write rejection below.
    case "$(uname -s 2>/dev/null || true)" in MINGW*|MSYS*) return 0 ;; esac
    mode="$(stat -c '%a' "$file" 2>/dev/null || true)"
    [[ "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
    mode="${mode: -3}"
    [[ "${mode:1:1}" == 0 && "${mode:2:1}" == 0 ]] || return 1
  fi
}

version_cache_reset_loaded() {
  VERSION_CACHE_APP_ID=""
  VERSION_CACHE_LATEST=""
  VERSION_CACHE_CHECKED_AT=""
  VERSION_CACHE_SOURCE=""
  VERSION_CACHE_RESULT=""
  VERSION_CACHE_EXPIRES_AT=""
  VERSION_CACHE_EXPIRES_AT_EPOCH=""
  VERSION_CACHE_FRESH=0
}

# Load and validate a successful cache entry. A malformed or unsafe entry is
# treated as a cache miss instead of being trusted as state.
version_cache_load() {
  local app_id="$1" file payload schema cached_app latest checked_at source result expires_at expires_at_epoch now
  version_cache_reset_loaded
  file="$(version_cache_file_for "$app_id")" || return 2
  version_cache_file_is_safe "$file" || return 1
  payload="$(cat "$file")" || return 1
  [[ "$(printf '%s\n' "$payload" | wc -l)" -eq 1 && "$payload" == \{*\} ]] || return 1
  schema="$(state_json_field "$payload" schema_version 2>/dev/null || true)"
  cached_app="$(state_json_field "$payload" app_id 2>/dev/null || true)"
  latest="$(state_json_field "$payload" latest 2>/dev/null || true)"
  checked_at="$(state_json_field "$payload" checked_at 2>/dev/null || true)"
  source="$(state_json_field "$payload" source 2>/dev/null || true)"
  result="$(state_json_field "$payload" result 2>/dev/null || true)"
  expires_at="$(state_json_field "$payload" expires_at 2>/dev/null || true)"
  expires_at_epoch="$(state_json_field "$payload" expires_at_epoch 2>/dev/null || true)"
  [[ "$schema" == "$DEPLOY_VERSION_CACHE_SCHEMA_VERSION" && "$cached_app" == "$app_id" && -n "$latest" && -n "$checked_at" && -n "$expires_at" && "$source" == github_release ]] || return 1
  case "$result" in up_to_date|update_available|unknown) ;; *) return 1 ;; esac
  [[ "$expires_at_epoch" =~ ^[0-9]+$ ]] || return 1
  now="$(version_check_now_epoch)"
  VERSION_CACHE_APP_ID="$cached_app"
  VERSION_CACHE_LATEST="$latest"
  VERSION_CACHE_CHECKED_AT="$checked_at"
  VERSION_CACHE_SOURCE="$source"
  VERSION_CACHE_RESULT="$result"
  VERSION_CACHE_EXPIRES_AT="$expires_at"
  VERSION_CACHE_EXPIRES_AT_EPOCH="$expires_at_epoch"
  (( now <= expires_at_epoch )) && VERSION_CACHE_FRESH=1
  return 0
}

version_check_result_for_versions() {
  local installed="$1" latest="$2" compared
  [[ -n "$installed" && -n "$latest" ]] || { printf 'unknown\n'; return 0; }
  deploy_version_is_stable "$installed" && deploy_version_is_stable "$latest" || { printf 'unknown\n'; return 0; }
  compared="$(deploy_version_compare "$latest" "$installed" 2>/dev/null)" || { printf 'unknown\n'; return 0; }
  case "$compared" in
    1) printf 'update_available\n' ;;
    0) printf 'up_to_date\n' ;;
    *) printf 'unknown\n' ;;
  esac
}

version_check_emit_json() {
  local installed="$1" latest="$2" checked_at="$3" update_state="$4" source="$5" cache_state="$6" error_summary="${7:-}"
  printf '{"installed":%s,"latest":%s,"checked_at":%s,"update_state":%s,"source":%s,"cache_state":%s,"error":%s}' \
    "$(state_json_nullable "$installed")" "$(state_json_nullable "$latest")" "$(state_json_nullable "$checked_at")" \
    "$(app_json_string "$update_state")" "$(app_json_string "$source")" "$(app_json_string "$cache_state")" \
    "$(state_json_nullable "$(operation_safe_summary "$error_summary")")"
}

version_cache_write() {
  local app_id="$1" latest="$2" checked_at="$3" result="$4" source="$5" now expires_at_epoch expires_at file
  now="$(version_check_now_epoch)"
  [[ "$now" =~ ^[0-9]+$ ]] || return 1
  [[ "$DEPLOY_VERSION_CACHE_TTL_SECONDS" =~ ^[0-9]+$ && "$DEPLOY_VERSION_CACHE_TTL_SECONDS" -gt 0 ]] || return 1
  expires_at_epoch=$((now + DEPLOY_VERSION_CACHE_TTL_SECONDS))
  expires_at="$(version_check_timestamp_for_epoch "$expires_at_epoch")" || return 1
  file="$(version_cache_file_for "$app_id")" || return 2
  version_cache_ensure_directory || return 1
  atomic_write_file "$file" 600 <<EOF
{"schema_version":${DEPLOY_VERSION_CACHE_SCHEMA_VERSION},"app_id":$(app_json_string "$app_id"),"checked_at":$(app_json_string "$checked_at"),"latest":$(app_json_string "$latest"),"source":$(app_json_string "$source"),"result":$(app_json_string "$result"),"expires_at":$(app_json_string "$expires_at"),"expires_at_epoch":${expires_at_epoch}}
EOF
}

# Return the last network check without making a network request. Expired
# cache data remains visible but is explicitly marked stale.
version_check_cached_binary_release_json() {
  local app_id="$1" installed="$2" cache_state=miss result
  if version_cache_load "$app_id"; then
    result="$(version_check_result_for_versions "$installed" "$VERSION_CACHE_LATEST")"
    if (( VERSION_CACHE_FRESH )); then
      cache_state=fresh
    else
      result=stale
      cache_state=stale
    fi
    version_check_emit_json "$installed" "$VERSION_CACHE_LATEST" "$VERSION_CACHE_CHECKED_AT" "$result" "$VERSION_CACHE_SOURCE" "$cache_state"
    return 0
  fi
  version_check_emit_json "$installed" "" "" unknown github_release "$cache_state"
}

# Check one binary application. refresh=1 always requests GitHub; without it,
# only cache misses or expired entries are refreshed. no_network=1 never calls
# curl and reports an expired cache as stale.
version_check_binary_release_json() {
  local app_id="$1" repo="$2" installed="$3" refresh="${4:-0}" no_network="${5:-0}"
  local latest checked_at result cache_state=miss
  [[ "$app_id" =~ ^[a-z][a-z0-9_-]{0,63}$ ]] || return 2
  [[ "$repo" =~ ^[A-Za-z0-9._-]+/[A-Za-z0-9._-]+$ ]] || {
    version_check_emit_json "$installed" "" "" unsupported github_release unsupported "binary release repository is not configured"
    return 0
  }
  if version_cache_load "$app_id"; then
    if (( ! refresh && VERSION_CACHE_FRESH )); then
      result="$(version_check_result_for_versions "$installed" "$VERSION_CACHE_LATEST")"
      version_check_emit_json "$installed" "$VERSION_CACHE_LATEST" "$VERSION_CACHE_CHECKED_AT" "$result" "$VERSION_CACHE_SOURCE" fresh
      return 0
    fi
    cache_state=stale
  fi
  if [[ "$no_network" == 1 ]]; then
    if [[ -n "$VERSION_CACHE_LATEST" ]]; then
      version_check_emit_json "$installed" "$VERSION_CACHE_LATEST" "$VERSION_CACHE_CHECKED_AT" stale "$VERSION_CACHE_SOURCE" stale
    else
      version_check_emit_json "$installed" "" "" unknown github_release no_network
    fi
    return 0
  fi
  if latest="$(github_latest_release_tag_checked "$repo")"; then
    checked_at="$(state_now)"
    result="$(version_check_result_for_versions "$installed" "$latest")"
    if version_cache_write "$app_id" "$latest" "$checked_at" "$result" github_release; then
      cache_state=refreshed
    else
      cache_state=not_persisted
    fi
    version_check_emit_json "$installed" "$latest" "$checked_at" "$result" github_release "$cache_state"
    return 0
  fi
  if [[ -n "$VERSION_CACHE_LATEST" ]]; then
    version_check_emit_json "$installed" "$VERSION_CACHE_LATEST" "$VERSION_CACHE_CHECKED_AT" stale "$VERSION_CACHE_SOURCE" stale "release check failed; using stale cache"
  else
    version_check_emit_json "$installed" "" "" check_failed github_release miss "release check failed"
  fi
}

# Check one git-branch application. The comparison is the local checkout HEAD
# against the remote branch head after a fetch; refs are not semver, so this
# never touches the version cache and always performs the network round trip
# unless no_network=1, which reports unknown without any fetch.
version_check_git_branch_json() {
  local repo_dir="$1" branch="$2" no_network="${3:-0}"
  local local_rev="" remote_rev result
  if [[ -n "$repo_dir" && -d "$repo_dir/.git" ]]; then
    local_rev="$(git -C "$repo_dir" rev-parse --short HEAD 2>/dev/null || true)"
  fi
  if [[ "$no_network" == 1 ]]; then
    version_check_emit_json "$local_rev" "" "" unknown git_branch miss
    return 0
  fi
  if [[ -z "$repo_dir" || ! -d "$repo_dir/.git" ]]; then
    version_check_emit_json "" "" "" check_failed git_branch miss "installation is not a git checkout"
    return 0
  fi
  if ! git -C "$repo_dir" fetch --quiet --prune origin "$branch" 2>/dev/null; then
    version_check_emit_json "$local_rev" "" "" check_failed git_branch miss "branch fetch failed"
    return 0
  fi
  remote_rev="$(git -C "$repo_dir" rev-parse --short "origin/${branch}" 2>/dev/null || true)"
  if [[ -z "$remote_rev" ]]; then
    version_check_emit_json "$local_rev" "" "" check_failed git_branch miss "cannot resolve remote branch head"
    return 0
  fi
  result=up_to_date
  [[ "$local_rev" != "$remote_rev" ]] && result=update_available
  version_check_emit_json "$local_rev" "$remote_rev" "$(state_now)" "$result" git_branch not_persisted
}

# ----- lib/manager_status.sh -----

MANAGER_STATUS_USAGE="Usage: deploy.sh status-all|overview|problems [--json] [--short] [--strict] [--errors-only] [--only-installed] [--no-probe] [--no-network] [--include id,id,...] [--exclude id,id,...]"

manager_status_print_usage() { echo "$MANAGER_STATUS_USAGE" >&2; }

manager_status_csv_ids() {
  local csv="$1" item id
  IFS=',' read -r -a items <<< "$csv"
  for item in "${items[@]}"; do
    id="$(deploy_trim "$item")"
    [[ -n "$id" ]] || continue
    deploy_app_offset_for "$id" >/dev/null 2>&1 || return 2
    printf '%s\n' "$id"
  done
}

manager_status_selected_ids() {
  local include_csv="${1:-}" exclude_csv="${2:-}" id excluded=0 parsed parse_status item
  local -a includes=() excludes=()
  if [[ -n "$include_csv" ]]; then
    set +e
    parsed="$(manager_status_csv_ids "$include_csv")"; parse_status=$?
    set -e
    (( parse_status == 0 )) || return 2
    [[ -n "$parsed" ]] && mapfile -t includes < <(printf '%s\n' "$parsed")
  else
    includes=("${DEPLOY_APP_IDS[@]}")
  fi
  if [[ -n "$exclude_csv" ]]; then
    set +e
    parsed="$(manager_status_csv_ids "$exclude_csv")"; parse_status=$?
    set -e
    (( parse_status == 0 )) || return 2
    [[ -n "$parsed" ]] && mapfile -t excludes < <(printf '%s\n' "$parsed")
  fi
  for id in "${includes[@]}"; do
    excluded=0
    for item in "${excludes[@]}"; do [[ "$id" == "$item" ]] && excluded=1; done
    (( excluded == 0 )) && printf '%s\n' "$id"
  done
  return 0
}

manager_status_collect_app_json() {
  local app_id="$1" output_file="$2" error_file="$3" status pid start timeout_seconds
  : >"$output_file"; : >"$error_file"
  ( manager_load_app "$app_id"; app_status_collect_json ) >"$output_file" 2>"$error_file" &
  pid=$!
  timeout_seconds="${DEPLOY_STATUS_TIMEOUT_SECONDS:-8}"
  if [[ "$timeout_seconds" =~ ^[0-9]+([.][0-9]+)?$ ]] && awk "BEGIN { exit !($timeout_seconds > 0) }"; then
    # `date` is relatively expensive on Git Bash/Windows. Calling it from the
    # polling loop used to add enough process churn to make healthy collectors
    # miss the timeout window. Bash's monotonic SECONDS variable avoids that
    # overhead while retaining the existing integer-second contract.
    local start_seconds=$SECONDS timeout_limit="${timeout_seconds%.*}"
    (( timeout_limit > 0 )) || timeout_limit=1
    while kill -0 "$pid" 2>/dev/null; do
      if (( SECONDS - start_seconds >= timeout_limit )); then
        kill "$pid" 2>/dev/null || true
        wait "$pid" 2>/dev/null || true
        printf 'status collection timed out after %ss' "$timeout_seconds" >>"$error_file"
        return 124
      fi
      sleep 0.1
    done
  fi
  if wait "$pid"; then
    status=0
  else
    status=$?
  fi
  [[ "$status" -eq 0 ]] || return "$status"
  [[ "$(wc -l < "$output_file")" -eq 1 ]] || { printf 'status collector returned multiple lines' >>"$error_file"; return 1; }
  [[ "$(head -c 1 "$output_file")" == "{" ]] || { printf 'status collector did not return a JSON object' >>"$error_file"; return 1; }
}

manager_status_json_field() {
  local file="$1" key="$2" object
  object="$(cat "$file")" || return 1
  state_json_field "$object" "$key"
}

manager_status_collect() {
  local include_csv="${1:-}" exclude_csv="${2:-}" only_installed="${3:-0}"
  local temp_dir app_id output error_file status parsed_ids
  local -a ids=() json_files=() errors=()
  temp_dir="$(mktemp -d)" || return 1
  chmod 700 "$temp_dir" || { rm -rf "$temp_dir"; return 1; }
  set +e
  parsed_ids="$(manager_status_selected_ids "$include_csv" "$exclude_csv")"; status=$?
  set -e
  if (( status != 0 )); then rm -rf "$temp_dir"; return 2; fi
  [[ -n "$parsed_ids" ]] && mapfile -t ids < <(printf '%s\n' "$parsed_ids")
  for app_id in "${ids[@]}"; do
    output="${temp_dir}/${app_id}.json"; error_file="${temp_dir}/${app_id}.err"
    if manager_status_collect_app_json "$app_id" "$output" "$error_file"; then
      if [[ "$only_installed" == 1 ]] && [[ "$(manager_status_json_field "$output" install_state)" != installed ]]; then continue; fi
      json_files+=("$output")
    else
      status=$?
      errors+=("${app_id}:${status}:$(operation_safe_summary "$(tr '\n' ' ' < "$error_file" 2>/dev/null)")")
    fi
  done
  printf '%s\n' "${json_files[@]}" >"${temp_dir}/files"
  printf '%s\n' "${errors[@]}" >"${temp_dir}/errors"
  MANAGER_STATUS_REGISTERED_COUNT="${#DEPLOY_APP_IDS[@]}"
  MANAGER_STATUS_SELECTED_COUNT="${#ids[@]}"
  MANAGER_STATUS_TEMP_DIR="$temp_dir"
}

manager_status_render_json() {
  local temp_dir="$1" problems="${2:-0}" errors_only="${3:-0}" file first=1 app_count=0 installed=0 healthy=0 degraded=0 unhealthy=0 not_installed=0 updates=0 error_count=0 severity registered
  registered="${MANAGER_STATUS_REGISTERED_COUNT:-0}"
  local selected="${MANAGER_STATUS_SELECTED_COUNT:-0}"
  local framework_mode=checkout framework_version=unknown
  [[ -f "${DEPLOY_ROOT_DIR}/.git/HEAD" ]] || framework_mode=standalone_dist
  while IFS= read -r file; do
    [[ -n "$file" ]] || continue
    severity="$(manager_status_human_field "$file" severity)"
    manager_status_should_render "$severity" 0 "$problems" "$errors_only" || continue
    app_count=$((app_count + 1))
    [[ "$(manager_status_json_field "$file" install_state)" == installed ]] && installed=$((installed + 1))
    case "$(manager_status_json_field "$file" health.state 2>/dev/null || true)" in healthy) healthy=$((healthy + 1));; degraded) degraded=$((degraded + 1));; unhealthy) unhealthy=$((unhealthy + 1));; esac
    [[ "$(manager_status_json_field "$file" install_state)" == not_installed ]] && not_installed=$((not_installed + 1))
    [[ "$(manager_status_json_field "$file" version_info.update_state 2>/dev/null || true)" == update_available ]] && updates=$((updates + 1))
  done <"${temp_dir}/files"
  error_count="$(grep -c . "${temp_dir}/errors" 2>/dev/null || true)"
  printf '{"schema_version":1,"generated_at":%s,"framework":{"version":%s,"install_mode":%s,"channel":"stable"},"summary":{"registered":%s,"selected":%s,"installed":%s,"healthy":%s,"degraded":%s,"unhealthy":%s,"not_installed":%s,"update_available":%s,"errors":%s},"apps":[' "$(app_json_string "$(state_now)")" "$(app_json_string "$framework_version")" "$(app_json_string "$framework_mode")" "$registered" "$selected" "$installed" "$healthy" "$degraded" "$unhealthy" "$not_installed" "$updates" "$error_count"
  while IFS= read -r file; do
    [[ -n "$file" ]] || continue
    severity="$(manager_status_human_field "$file" severity)"
    manager_status_should_render "$severity" 0 "$problems" "$errors_only" || continue
    (( first )) || printf ','; first=0; cat "$file"
  done <"${temp_dir}/files"
  printf '],"errors":['; first=1
  while IFS= read -r file; do
    [[ -n "$file" ]] || continue
    (( first )) || printf ','; first=0
    local app_id code summary; app_id="${file%%:*}"; code="${file#*:}"; code="${code%%:*}"; summary="${file#*:*:}"
    printf '{"app_id":%s,"code":%s,"summary":%s}' "$(app_json_string "$app_id")" "$code" "$(app_json_string "$summary")"
  done <"${temp_dir}/errors"
  printf ']}\n'
}

manager_status_human_field() { local file="$1" key="$2"; manager_status_json_field "$file" "$key" 2>/dev/null || printf unknown; }

manager_status_should_render() {
  local severity="$1" short="${2:-0}" problems="${3:-0}" errors_only="${4:-0}"
  if [[ "$errors_only" == 1 ]]; then
    [[ "$severity" == critical || "$severity" == error ]]
  elif [[ "$problems" == 1 || "$short" == 1 ]]; then
    [[ "$severity" == critical || "$severity" == error || "$severity" == warning ]]
  else
    return 0
  fi
}

manager_status_render_table() {
  local temp_dir="$1" short="${2:-0}" problems="${3:-0}" errors_only="${4:-0}" file app_id name install severity service health version
  printf '%-16s %-24s %-15s %-10s %-12s %-12s %-18s\n' App Name Install Severity Service Health Version
  printf '%-16s %-24s %-15s %-10s %-12s %-12s %-18s\n' '----------------' '------------------------' '---------------' '----------' '------------' '------------' '------------------'
  while IFS= read -r file; do
    [[ -n "$file" ]] || continue
    install="$(manager_status_human_field "$file" install_state)"; severity="$(manager_status_human_field "$file" severity)"
    manager_status_should_render "$severity" "$short" "$problems" "$errors_only" || continue
    app_id="$(manager_status_human_field "$file" app_id)"; name="$(manager_status_human_field "$file" app_name)"; service="$(manager_status_human_field "$file" service.state)"; health="$(manager_status_human_field "$file" health.state)"; version="$(manager_status_human_field "$file" version_info.installed)"
    printf '%-16s %-24s %-15s %-10s %-12s %-12s %-18s\n' "$app_id" "$name" "$install" "$severity" "$service" "$health" "$version"
  done <"${temp_dir}/files"
  while IFS= read -r file; do [[ -n "$file" ]] && printf 'error: %s\n' "$file" >&2; done <"${temp_dir}/errors"
}

manager_status_main() {
  local command="$1" arg json=0 short=0 strict=0 errors_only=0 only_installed=0 include_csv="" exclude_csv="" temp_dir status
  shift || true
  while (($#)); do
    arg="$1"; shift
    case "$arg" in
      --json) json=1 ;;
      --short) short=1 ;;
      --strict) strict=1 ;;
      --errors-only) errors_only=1 ;;
      --only-installed) only_installed=1 ;;
      --no-probe) export DEPLOY_STATUS_NO_PROBE=1 ;;
      --no-network) export DEPLOY_STATUS_NO_NETWORK=1 ;;
      --include) (($#)) || { manager_status_print_usage; return 2; }; include_csv="$1"; shift ;;
      --exclude) (($#)) || { manager_status_print_usage; return 2; }; exclude_csv="$1"; shift ;;
      --include=*) include_csv="${arg#*=}" ;;
      --exclude=*) exclude_csv="${arg#*=}" ;;
      *) manager_status_print_usage; return 2 ;;
    esac
  done
  [[ "$command" != problems ]] || strict=1
  [[ "$command" != health-all ]] || only_installed=1
  manager_status_collect "$include_csv" "$exclude_csv" "$only_installed" || return $?
  temp_dir="$MANAGER_STATUS_TEMP_DIR"
  if (( json )); then
    manager_status_render_json "$temp_dir" "$([[ "$command" == problems ]] && printf 1 || printf 0)" "$errors_only"
  else
    manager_status_render_table "$temp_dir" "$short" "$([[ "$command" == problems ]] && printf 1 || printf 0)" "$errors_only"
  fi
  status=0
  if (( strict )); then
    if grep -q "[^[:space:]]" "${temp_dir}/errors" 2>/dev/null; then
      status=1
    fi
    while IFS= read -r file; do
      [[ -n "$file" ]] || continue
      case "$(manager_status_human_field "$file" severity)" in
        critical) status=7 ;;
        error)
          case "$(manager_status_human_field "$file" service.state)" in failed|stopped) (( status < 4 )) && status=4 ;; esac
          case "$(manager_status_human_field "$file" health.state)" in unhealthy) (( status < 5 )) && status=5 ;; esac
          (( status == 0 )) && status=1
          ;;
        warning)
          case "$(manager_status_human_field "$file" health.state)" in degraded) (( status < 5 )) && status=5 ;; *) (( status < 1 )) && status=1 ;; esac
          ;;
      esac
    done <"${temp_dir}/files"
  fi
  rm -rf "$temp_dir"
  return "$status"
}

# ----- lib/manager_history.sh -----

MANAGER_HISTORY_USAGE="Usage: deploy.sh history [app-id] [--json] [--limit N]"

manager_history_print_usage() { echo "$MANAGER_HISTORY_USAGE" >&2; }

manager_history_validate_app() {
  local app_id="$1"
  [[ -z "$app_id" ]] && return 0
  deploy_app_offset_for "$app_id" >/dev/null 2>&1
}

manager_history_raw_or_null() {
  local record="$1" field="$2" raw
  raw="$(state_json_raw_field "$record" "$field" 2>/dev/null || true)"
  [[ -n "$raw" ]] && printf '%s' "$raw" || printf 'null'
}

manager_history_record_json() {
  local record="$1" expected_app="${2:-}" app_id scope run_id action state started_at finished_at exit_code error log_path
  app_id="$(state_json_field "$record" app_id 2>/dev/null || true)"
  [[ -z "$expected_app" || "$app_id" == "$expected_app" ]] || return 3
  scope="$(state_json_field "$record" scope 2>/dev/null || true)"
  run_id="$(state_json_field "$record" run_id 2>/dev/null || true)"
  action="$(state_json_field "$record" action 2>/dev/null || true)"
  state="$(state_json_field "$record" state 2>/dev/null || true)"
  started_at="$(state_json_field "$record" started_at 2>/dev/null || true)"
  [[ -n "$scope" && -n "$run_id" && -n "$action" && -n "$state" && -n "$started_at" ]] || return 1
  finished_at="$(state_json_field "$record" finished_at 2>/dev/null || true)"
  exit_code="$(manager_history_raw_or_null "$record" exit_code)"
  [[ "$exit_code" =~ ^[0-9]+$ ]] || exit_code=null
  error="$(state_json_field "$record" error 2>/dev/null || true)"
  log_path="$(state_json_field "$record" log_path 2>/dev/null || true)"
  printf '{"run_id":%s,"scope":%s,"app_id":%s,"action":%s,"state":%s,"started_at":%s,"finished_at":%s,"exit_code":%s,"error":%s,"log_path":%s}\n' \
    "$(app_json_string "$run_id")" "$(app_json_string "$scope")" "$(state_json_nullable "$app_id")" \
    "$(app_json_string "$action")" "$(app_json_string "$state")" "$(app_json_string "$started_at")" \
    "$(state_json_nullable "$finished_at")" "$exit_code" "$(state_json_nullable "$(operation_safe_summary "$error")")" "$(state_json_nullable "$log_path")"
}

manager_history_collect() {
  local app_id="${1:-}" limit="$2" history_file record index
  MANAGER_HISTORY_RECORDS=()
  MANAGER_HISTORY_SKIPPED=0
  history_file="${DEPLOY_OPERATION_HISTORY_FILE}"
  [[ -f "$history_file" ]] || return 0
  mapfile -t records < <(tail -n "$limit" "$history_file" 2>/dev/null || true)
  for ((index = ${#records[@]} - 1; index >= 0; index--)); do
    if record="$(manager_history_record_json "${records[index]}" "$app_id" 2>/dev/null)"; then
      MANAGER_HISTORY_RECORDS+=("$record")
    else
      case $? in
        3) ;;
        *) MANAGER_HISTORY_SKIPPED=$((MANAGER_HISTORY_SKIPPED + 1)) ;;
      esac
    fi
  done
}

manager_history_render_json() {
  local app_id="$1" first=1 record
  printf '{"schema_version":1,"generated_at":%s,"app_id":%s,"records":[' "$(app_json_string "$(state_now)")" "$(state_json_nullable "$app_id")"
  for record in "${MANAGER_HISTORY_RECORDS[@]}"; do
    (( first )) || printf ','
    first=0
    printf '%s' "$record"
  done
  printf '],"skipped_records":%s}\n' "$MANAGER_HISTORY_SKIPPED"
}

manager_history_render_table() {
  local record run_id app_id action state started_at finished_at error
  printf '%-30s %-16s %-14s %-14s %-25s %-25s %s\n' Run App Action State Started Finished Error
  printf '%-30s %-16s %-14s %-14s %-25s %-25s %s\n' '------------------------------' '----------------' '--------------' '--------------' '-------------------------' '-------------------------' '-----'
  for record in "${MANAGER_HISTORY_RECORDS[@]}"; do
    run_id="$(state_json_field "$record" run_id)"
    app_id="$(state_json_field "$record" app_id)"
    action="$(state_json_field "$record" action)"
    state="$(state_json_field "$record" state)"
    started_at="$(state_json_field "$record" started_at)"
    finished_at="$(state_json_field "$record" finished_at)"
    error="$(state_json_field "$record" error 2>/dev/null || true)"
    printf '%-30s %-16s %-14s %-14s %-25s %-25s %s\n' "$run_id" "$app_id" "$action" "$state" "$started_at" "$finished_at" "$error"
  done
  (( MANAGER_HISTORY_SKIPPED == 0 )) || printf 'Skipped malformed history records: %s\n' "$MANAGER_HISTORY_SKIPPED" >&2
}

manager_history_main() {
  local app_id="" limit=20 json=0 arg
  while (($#)); do
    arg="$1"; shift
    case "$arg" in
      --json) json=1 ;;
      --limit)
        (($#)) || { manager_history_print_usage; return 2; }
        limit="$1"; shift
        ;;
      --limit=*) limit="${arg#*=}" ;;
      --help|-h) manager_history_print_usage; return 0 ;;
      --*) manager_history_print_usage; return 2 ;;
      *)
        [[ -z "$app_id" ]] || { manager_history_print_usage; return 2; }
        app_id="$arg"
        ;;
    esac
  done
  [[ "$limit" =~ ^[1-9][0-9]*$ && "$limit" -le 200 ]] || { manager_history_print_usage; return 2; }
  manager_history_validate_app "$app_id" || return 2
  manager_history_collect "$app_id" "$limit"
  if (( json )); then manager_history_render_json "$app_id"; else manager_history_render_table; fi
}

# ----- lib/manager_doctor.sh -----

MANAGER_DOCTOR_USAGE="Usage: deploy.sh doctor-all [--json] [--only-installed] [--include id,id,...] [--exclude id,id,...]"

manager_doctor_print_usage() { echo "$MANAGER_DOCTOR_USAGE" >&2; }

manager_doctor_record() {
  local app_id="$1" state="$2" status="$3" output="$4" reason="${5:-}"
  local status_json=null
  [[ "$status" =~ ^[0-9]+$ ]] && status_json="$status"
  printf '{"app_id":%s,"state":%s,"status":%s,"reason":%s,"output":%s}' \
    "$(app_json_string "$app_id")" "$(app_json_string "$state")" "$status_json" \
    "$(state_json_nullable "$(operation_safe_summary "$reason")")" \
    "$(state_json_nullable "$(operation_safe_summary "$output" 4096)")"
}

manager_doctor_main() {
  local json=0 only_installed=1 include_csv="" exclude_csv="" arg app_id selected
  local installed=0 succeeded=0 failed=0 skipped=0 errors=0
  local -a ids=() records=()
  while (($#)); do
    arg="$1"; shift
    case "$arg" in
      --json) json=1 ;;
      --only-installed) only_installed=1 ;;
      --include) (($#)) || { manager_doctor_print_usage; return 2; }; include_csv="$1"; shift ;;
      --exclude) (($#)) || { manager_doctor_print_usage; return 2; }; exclude_csv="$1"; shift ;;
      --include=*) include_csv="${arg#*=}" ;;
      --exclude=*) exclude_csv="${arg#*=}" ;;
      --help|-h) manager_doctor_print_usage; return 0 ;;
      *) manager_doctor_print_usage; return 2 ;;
    esac
  done
  if ! selected="$(manager_status_selected_ids "$include_csv" "$exclude_csv")"; then return 2; fi
  [[ -n "$selected" ]] && mapfile -t ids < <(printf '%s\n' "$selected")

  for app_id in "${ids[@]}"; do
    local state_file err_file install_state collection_error
    state_file="$(mktemp)"; err_file="$(mktemp)"
    # Target selection is a local read-only pass. Do not run health probes or
    # remote checks here; the batch action itself decides what to execute.
    if ! ( DEPLOY_STATUS_NO_PROBE=1 DEPLOY_STATUS_NO_NETWORK=1
           manager_status_collect_app_json "$app_id" "$state_file" "$err_file" ); then
      collection_error="$(tr '\n' ' ' < "$err_file" 2>/dev/null || true)"
      records+=("$(manager_doctor_record "$app_id" error "" "$collection_error" "status_collection_failed")")
      errors=$((errors + 1))
      rm -f "$state_file" "$err_file"
      continue
    fi
    install_state="$(manager_status_json_field "$state_file" install_state 2>/dev/null || printf unknown)"
    if [[ "$only_installed" == 1 && "$install_state" != installed ]]; then
      records+=("$(manager_doctor_record "$app_id" skipped null "" "not_installed")")
      skipped=$((skipped + 1))
      rm -f "$state_file" "$err_file"
      continue
    fi
    installed=$((installed + 1))
    local doctor_output doctor_status
    if doctor_output="$(manager_load_app "$app_id" 2>&1 && do_doctor 2>&1)"; then
      doctor_status=0
      succeeded=$((succeeded + 1))
      records+=("$(manager_doctor_record "$app_id" succeeded "$doctor_status" "$doctor_output")")
    else
      doctor_status=$?
      failed=$((failed + 1))
      records+=("$(manager_doctor_record "$app_id" failed "$doctor_status" "$doctor_output" "doctor_failed")")
    fi
    rm -f "$state_file" "$err_file"
  done

  if (( json )); then
    local first=1 record
    printf '{"schema_version":1,"generated_at":%s,"summary":{"selected":%s,"installed":%s,"succeeded":%s,"failed":%s,"skipped":%s,"errors":%s},"records":[' \
      "$(app_json_string "$(state_now)")" "${#ids[@]}" "$installed" "$succeeded" "$failed" "$skipped" "$errors"
    for record in "${records[@]}"; do (( first )) || printf ','; first=0; printf '%s' "$record"; done
    printf ']}\n'
  else
    printf '%-16s %-12s %-8s %-18s %s\n' App State Status Reason Output
    for record in "${records[@]}"; do
      printf '%-16s %-12s %-8s %-18s %s\n' \
        "$(state_json_field "$record" app_id)" "$(state_json_field "$record" state)" \
        "$(state_json_field "$record" status)" "$(state_json_field "$record" reason)" \
        "$(state_json_field "$record" output)"
    done
  fi
  (( failed == 0 && errors == 0 ))
}

# ----- lib/manager_backup.sh -----

MANAGER_BACKUP_USAGE="Usage: deploy.sh backup-all [--dry-run] [--yes] [--json] [--include id,id,...] [--exclude id,id,...]"

manager_backup_print_usage() { echo "$MANAGER_BACKUP_USAGE" >&2; }

manager_backup_capability() {
  local app_id="$1" body
  manager_load_app "$app_id" || return 1
  load_app_impl || return 1
  if ! declare -f do_backup >/dev/null 2>&1; then
    printf unsupported
    return 0
  fi
  body="$(declare -f do_backup)"
  if [[ "$body" == *unsupported_action* ]]; then
    printf unsupported
  else
    printf supported
  fi
}

manager_backup_record() {
  local app_id="$1" install_state="$2" capability="$3" action="$4" reason="${5:-}" error_summary="${6:-}" status="${7:-}"
  local status_json=null
  [[ "$status" =~ ^[0-9]+$ ]] && status_json="$status"
  printf '{"app_id":%s,"install_state":%s,"backup":%s,"action":%s,"reason":%s,"status":%s,"error":%s}' \
    "$(app_json_string "$app_id")" "$(app_json_string "$install_state")" \
    "$(app_json_string "$capability")" "$(app_json_string "$action")" \
    "$(state_json_nullable "$reason")" "$status_json" \
    "$(state_json_nullable "$(operation_safe_summary "$error_summary")")"
}

manager_backup_confirm() {
  local yes="$1" planned="$2" answer
  [[ "$yes" == 1 || "${DEPLOY_ASSUME_YES:-0}" == 1 ]] && return 0
  if [[ ! -t 0 ]]; then
    echo 'backup-all requires --yes or DEPLOY_ASSUME_YES=1 when standard input is not interactive.' >&2
    return 2
  fi
  printf 'Backup %s application(s)? [y/N] ' "$planned" >&2
  read -r answer
  [[ "${answer,,}" == y || "${answer,,}" == yes ]]
}

manager_backup_operation_log() {
  [[ "${MANAGER_BACKUP_OPERATION_ACTIVE:-0}" == 1 ]] || return 0
  operation_redact_line "$1" >>"$OPERATION_LOG_PATH" || true
}

manager_backup_operation_exit_handler() {
  local status=$?
  [[ "${MANAGER_BACKUP_OPERATION_ACTIVE:-0}" == 1 ]] || return 0
  MANAGER_BACKUP_OPERATION_ACTIVE=0
  operation_step_finish execute failed >/dev/null 2>&1 || true
  operation_finish "$status" "" "backup-all exited with status ${status}" >/dev/null 2>&1 || true
}

manager_backup_operation_start() {
  operation_start manager "" backup-all || return 1
  operation_step_start execute >/dev/null 2>&1 || {
    operation_finish 1 failed "failed to start execute step" >/dev/null 2>&1 || true
    return 1
  }
  MANAGER_BACKUP_OPERATION_ACTIVE=1
  deploy_add_exit_handler manager_backup_operation_exit_handler
  manager_backup_operation_log "backup-all started planned=${MANAGER_BACKUP_PLANNED:-0}"
}

manager_backup_operation_finish() {
  local status="$1" summary="${2:-}"
  [[ "${MANAGER_BACKUP_OPERATION_ACTIVE:-0}" == 1 ]] || return 0
  MANAGER_BACKUP_OPERATION_ACTIVE=0
  if (( status == 0 )); then
    operation_step_finish execute succeeded >/dev/null 2>&1 || true
  else
    operation_step_finish execute failed >/dev/null 2>&1 || true
  fi
  operation_finish "$status" "" "$summary" >/dev/null 2>&1 || true
}

manager_backup_execute_app() {
  local app_id="$1"
  manager_load_app "$app_id"
  dispatch_action backup
}

manager_backup_main() {
  local dry_run=0 json=0 yes=0 include_csv="" exclude_csv="" arg selected app_id state_file err_file install_state capability collection_error
  local planned=0 skipped=0 errors=0 updated=0 failed=0 status=0 first=1 record plan_record action
  local -a ids=() records=() plan_records=()
  while (($#)); do
    arg="$1"; shift
    case "$arg" in
      --dry-run) dry_run=1 ;;
      --yes) yes=1 ;;
      --json) json=1 ;;
      --include) (($#)) || { manager_backup_print_usage; return 2; }; include_csv="$1"; shift ;;
      --exclude) (($#)) || { manager_backup_print_usage; return 2; }; exclude_csv="$1"; shift ;;
      --include=*) include_csv="${arg#*=}" ;;
      --exclude=*) exclude_csv="${arg#*=}" ;;
      --help|-h) manager_backup_print_usage; return 0 ;;
      *) manager_backup_print_usage; return 2 ;;
    esac
  done
  if ! selected="$(manager_status_selected_ids "$include_csv" "$exclude_csv")"; then return 2; fi
  [[ -n "$selected" ]] && mapfile -t ids < <(printf '%s\n' "$selected")

  for app_id in "${ids[@]}"; do
    state_file="$(mktemp)"; err_file="$(mktemp)"
    if ! ( DEPLOY_STATUS_NO_PROBE=1 DEPLOY_STATUS_NO_NETWORK=1
           manager_status_collect_app_json "$app_id" "$state_file" "$err_file" ); then
      collection_error="$(tr '\n' ' ' < "$err_file" 2>/dev/null || true)"
      plan_records+=("$(manager_backup_record "$app_id" unknown unknown error collection_failed "$collection_error")")
      errors=$((errors + 1))
      rm -f "$state_file" "$err_file"
      continue
    fi
    install_state="$(manager_status_json_field "$state_file" install_state 2>/dev/null || printf unknown)"
    if [[ "$install_state" != installed ]]; then
      plan_records+=("$(manager_backup_record "$app_id" "$install_state" unsupported skip not_installed)")
      skipped=$((skipped + 1))
      rm -f "$state_file" "$err_file"
      continue
    fi
    if capability="$(manager_backup_capability "$app_id" 2>/dev/null)" && [[ "$capability" == supported || "$capability" == unsupported ]]; then
      if [[ "$capability" == supported ]]; then
        planned=$((planned + 1))
        plan_records+=("$(manager_backup_record "$app_id" "$install_state" "$capability" plan supported)")
      else
        skipped=$((skipped + 1))
        plan_records+=("$(manager_backup_record "$app_id" "$install_state" "$capability" skip unsupported)")
      fi
    else
      collection_error="backup capability detection failed"
      plan_records+=("$(manager_backup_record "$app_id" "$install_state" unknown error capability_failed "$collection_error")")
      errors=$((errors + 1))
    fi
    rm -f "$state_file" "$err_file"
  done

  if (( dry_run )); then
    if (( json )); then
      printf '{"schema_version":1,"generated_at":%s,"dry_run":true,"summary":{"selected":%s,"planned":%s,"skipped":%s,"errors":%s},"records":[' \
        "$(app_json_string "$(state_now)")" "${#ids[@]}" "$planned" "$skipped" "$errors"
      for record in "${plan_records[@]}"; do (( first )) || printf ','; first=0; printf '%s' "$record"; done
      printf ']}\n'
    else
      printf 'backup-all dry-run: selected=%s planned=%s skipped=%s errors=%s\n' "${#ids[@]}" "$planned" "$skipped" "$errors"
      for record in "${plan_records[@]}"; do printf '%s\n' "$record"; done
    fi
    (( errors == 0 )) || return 1
    return 0
  fi

  if (( planned > 0 )); then
    if (( json )) && [[ "$yes" != 1 && "${DEPLOY_ASSUME_YES:-0}" != 1 ]]; then
      echo 'backup-all --json with planned backups requires --yes or DEPLOY_ASSUME_YES=1.' >&2
      return 2
    fi
    manager_backup_confirm "$yes" "$planned" || return $?
    manager_update_acquire_lock
    status=$?
    if (( status != 0 )); then
      echo 'Unable to acquire the manager backup lock.' >&2
      return "$status"
    fi
    MANAGER_BACKUP_PLANNED="$planned"
    manager_backup_operation_start || {
      manager_update_release_lock
      echo 'Unable to start manager backup operation record.' >&2
      return 1
    }
  fi

  for plan_record in "${plan_records[@]}"; do
    action="$(state_json_field "$plan_record" action)"
    if [[ "$action" != plan ]]; then
      records+=("$plan_record")
      continue
    fi
    app_id="$(state_json_field "$plan_record" app_id)"
    if (( json )); then
      if ( manager_backup_execute_app "$app_id" ) >&2; then status=0; else status=$?; fi
    else
      printf '\n== Backing up %s ==\n' "$app_id"
      if ( manager_backup_execute_app "$app_id" ); then status=0; else status=$?; fi
    fi
    if (( status == 0 )); then
      updated=$((updated + 1))
      records+=("$(manager_backup_record "$app_id" installed supported succeeded completed "" "$status")")
      manager_backup_operation_log "app=${app_id} state=succeeded status=${status}"
    else
      failed=$((failed + 1))
      records+=("$(manager_backup_record "$app_id" installed supported failed backup_failed "$status" "$status")")
      manager_backup_operation_log "app=${app_id} state=failed status=${status}"
    fi
  done
  (( planned > 0 )) && manager_update_release_lock
  if (( failed == 0 && errors == 0 )); then
    manager_backup_operation_finish 0 "backup-all completed successfully"
  else
    manager_backup_operation_finish 1 "backup-all completed with ${failed} failed application(s)"
  fi

  if (( json )); then
    first=1
    printf '{"schema_version":1,"generated_at":%s,"dry_run":false,"summary":{"selected":%s,"planned":%s,"updated":%s,"failed":%s,"skipped":%s,"errors":%s},"records":[' \
      "$(app_json_string "$(state_now)")" "${#ids[@]}" "$planned" "$updated" "$failed" "$skipped" "$errors"
    for record in "${records[@]}"; do (( first )) || printf ','; first=0; printf '%s' "$record"; done
    printf ']}\n'
  else
    printf '\nbackup-all: selected=%s planned=%s completed=%s failed=%s skipped=%s errors=%s\n' \
      "${#ids[@]}" "$planned" "$updated" "$failed" "$skipped" "$errors"
  fi
  (( failed == 0 && errors == 0 )) || return 1
}

# ----- lib/manager_update.sh -----

MANAGER_UPDATE_USAGE="Usage: deploy.sh check-update [--json] [--refresh|--no-network] [--include id,id,...] [--exclude id,id,...]"
MANAGER_UPDATE_ALL_USAGE="Usage: deploy.sh update-all [--dry-run] [--yes] [--json] [--refresh|--no-network] [--include id,id,...] [--exclude id,id,...]"

manager_update_print_usage() { echo "$MANAGER_UPDATE_USAGE" >&2; }
manager_update_all_print_usage() { echo "$MANAGER_UPDATE_ALL_USAGE" >&2; }

manager_update_record() {
  local app_id="$1" app_name="$2" install_state="$3" state="$4" reason="$5" version_json="$6"
  printf '{"app_id":%s,"app_name":%s,"install_state":%s,"state":%s,"reason":%s,"version":%s}' \
    "$(app_json_string "$app_id")" "$(app_json_string "$app_name")" \
    "$(app_json_string "$install_state")" "$(app_json_string "$state")" \
    "$(state_json_nullable "$reason")" "$version_json"
}

manager_update_unsupported_version_json() {
  local installed="$1" reason="$2"
  version_check_emit_json "$installed" "" "" unsupported config unsupported "$reason"
}

# All application loading happens in a subshell. Implementations set global
# defaults and hooks, and isolation prevents one application's BA_* settings
# from being mistaken for another application's capability.
#
# Applications outside the shared binary-app lifecycle opt in through
# APP_CHECK_UPDATE_FN, which must emit the same single-line version JSON
# contract as bapp_check_update_json (see version_check_emit_json).
manager_update_check_app_version() {
  local app_id="$1" installed="$2" refresh="$3" no_network="$4"
  manager_load_app "$app_id" || return 1
  if [[ -n "${APP_CHECK_UPDATE_FN:-}" ]] && declare -f "$APP_CHECK_UPDATE_FN" >/dev/null 2>&1; then
    "$APP_CHECK_UPDATE_FN" "$installed" "$refresh" "$no_network"
    return 0
  fi
  if [[ -z "${BA_BIN_NAME:-}" ]] || ! declare -f bapp_check_update_json >/dev/null 2>&1; then
    manager_update_unsupported_version_json "$installed" "version checking is not supported"
    return 0
  fi
  bapp_check_update_json "$installed" "$refresh" "$no_network"
}

# Populate a reusable, stable assessment for check-update and update-all
# planning. This is intentionally serial: GitHub API requests should not burst
# across all apps, and the later write path must remain deterministic.
manager_update_collect() {
  local refresh="$1" no_network="$2" include_csv="$3" exclude_csv="$4"
  local selected app_id app_name state_file err_file install_state config_safe installed version_json update_state record_state reason collection_error
  MANAGER_UPDATE_SELECTED=0
  MANAGER_UPDATE_INSTALLED=0
  MANAGER_UPDATE_AVAILABLE=0
  MANAGER_UPDATE_CURRENT=0
  MANAGER_UPDATE_UNSUPPORTED=0
  MANAGER_UPDATE_UNKNOWN=0
  MANAGER_UPDATE_STALE=0
  MANAGER_UPDATE_CHECK_FAILED=0
  MANAGER_UPDATE_ERRORS=0
  MANAGER_UPDATE_RECORDS=()
  local -a ids=()

  if ! selected="$(manager_status_selected_ids "$include_csv" "$exclude_csv")"; then return 2; fi
  [[ -n "$selected" ]] && mapfile -t ids < <(printf '%s\n' "$selected")
  MANAGER_UPDATE_SELECTED="${#ids[@]}"
  for app_id in "${ids[@]}"; do
    app_name="$(deploy_app_name_for "$app_id")"
    state_file="$(mktemp)"; err_file="$(mktemp)"
    # Target selection must not trigger health probes or remote lookups. Version
    # refresh, when requested, is handled separately by the version adapter.
    if ! ( DEPLOY_STATUS_NO_PROBE=1 DEPLOY_STATUS_NO_NETWORK=1
           manager_status_collect_app_json "$app_id" "$state_file" "$err_file" ); then
      collection_error="$(tr '\n' ' ' < "$err_file" 2>/dev/null || true)"
      version_json="$(version_check_emit_json "" "" "" check_failed config miss "$collection_error")"
      MANAGER_UPDATE_RECORDS+=("$(manager_update_record "$app_id" "$app_name" unknown error status_collection_failed "$version_json")")
      MANAGER_UPDATE_ERRORS=$((MANAGER_UPDATE_ERRORS + 1))
      rm -f "$state_file" "$err_file"
      continue
    fi
    install_state="$(manager_status_json_field "$state_file" install_state 2>/dev/null || printf unknown)"
    if [[ "$install_state" != installed ]]; then
      version_json="$(manager_update_unsupported_version_json "" "application is not installed")"
      MANAGER_UPDATE_RECORDS+=("$(manager_update_record "$app_id" "$app_name" "$install_state" skipped not_installed "$version_json")")
      rm -f "$state_file" "$err_file"
      continue
    fi
    MANAGER_UPDATE_INSTALLED=$((MANAGER_UPDATE_INSTALLED + 1))
    config_safe="$(manager_status_json_field "$state_file" config.safe 2>/dev/null || printf false)"
    installed="$(manager_status_json_field "$state_file" version.installed 2>/dev/null || true)"
    [[ "$installed" == null ]] && installed=""
    if [[ "$config_safe" != true ]]; then
      version_json="$(version_check_emit_json "$installed" "" "" unknown config blocked "managed configuration is unsafe")"
      MANAGER_UPDATE_RECORDS+=("$(manager_update_record "$app_id" "$app_name" "$install_state" skipped unsafe_config "$version_json")")
      MANAGER_UPDATE_UNKNOWN=$((MANAGER_UPDATE_UNKNOWN + 1))
      rm -f "$state_file" "$err_file"
      continue
    fi
    if version_json="$(manager_update_check_app_version "$app_id" "$installed" "$refresh" "$no_network" 2>"$err_file")"; then
      update_state="$(state_json_field "$version_json" update_state 2>/dev/null || printf check_failed)"
      reason=""
      record_state=checked
      case "$update_state" in
        update_available) MANAGER_UPDATE_AVAILABLE=$((MANAGER_UPDATE_AVAILABLE + 1)) ;;
        up_to_date) MANAGER_UPDATE_CURRENT=$((MANAGER_UPDATE_CURRENT + 1)) ;;
        unsupported) MANAGER_UPDATE_UNSUPPORTED=$((MANAGER_UPDATE_UNSUPPORTED + 1)); record_state=skipped; reason=unsupported ;;
        stale) MANAGER_UPDATE_STALE=$((MANAGER_UPDATE_STALE + 1)) ;;
        unknown) MANAGER_UPDATE_UNKNOWN=$((MANAGER_UPDATE_UNKNOWN + 1)) ;;
        check_failed) MANAGER_UPDATE_CHECK_FAILED=$((MANAGER_UPDATE_CHECK_FAILED + 1)); record_state=error; reason=release_check_failed ;;
        *) MANAGER_UPDATE_CHECK_FAILED=$((MANAGER_UPDATE_CHECK_FAILED + 1)); record_state=error; reason=invalid_version_result ;;
      esac
      MANAGER_UPDATE_RECORDS+=("$(manager_update_record "$app_id" "$app_name" "$install_state" "$record_state" "$reason" "$version_json")")
    else
      collection_error="$(tr '\n' ' ' < "$err_file" 2>/dev/null || true)"
      version_json="$(version_check_emit_json "$installed" "" "" check_failed config miss "$collection_error")"
      MANAGER_UPDATE_RECORDS+=("$(manager_update_record "$app_id" "$app_name" "$install_state" error version_adapter_failed "$version_json")")
      MANAGER_UPDATE_ERRORS=$((MANAGER_UPDATE_ERRORS + 1))
    fi
    rm -f "$state_file" "$err_file"
  done
}

manager_update_collect_status() {
  (( MANAGER_UPDATE_ERRORS == 0 )) || return 1
  (( MANAGER_UPDATE_CHECK_FAILED == 0 )) || return 10
  return 0
}

manager_update_render_check_json() {
  local refresh="$1" no_network="$2" first=1 record
  printf '{"schema_version":1,"generated_at":%s,"refresh":%s,"no_network":%s,"summary":{"selected":%s,"installed":%s,"update_available":%s,"up_to_date":%s,"unsupported":%s,"unknown":%s,"stale":%s,"check_failed":%s,"errors":%s},"records":[' \
    "$(app_json_string "$(state_now)")" "$([[ "$refresh" == 1 ]] && printf true || printf false)" "$([[ "$no_network" == 1 ]] && printf true || printf false)" \
    "$MANAGER_UPDATE_SELECTED" "$MANAGER_UPDATE_INSTALLED" "$MANAGER_UPDATE_AVAILABLE" "$MANAGER_UPDATE_CURRENT" "$MANAGER_UPDATE_UNSUPPORTED" "$MANAGER_UPDATE_UNKNOWN" "$MANAGER_UPDATE_STALE" "$MANAGER_UPDATE_CHECK_FAILED" "$MANAGER_UPDATE_ERRORS"
  for record in "${MANAGER_UPDATE_RECORDS[@]}"; do (( first )) || printf ','; first=0; printf '%s' "$record"; done
  printf ']}\n'
}

manager_update_render_check_table() {
  local record
  printf 'check-update: selected=%s installed=%s update_available=%s up_to_date=%s unsupported=%s unknown=%s stale=%s check_failed=%s errors=%s\n' \
    "$MANAGER_UPDATE_SELECTED" "$MANAGER_UPDATE_INSTALLED" "$MANAGER_UPDATE_AVAILABLE" "$MANAGER_UPDATE_CURRENT" "$MANAGER_UPDATE_UNSUPPORTED" "$MANAGER_UPDATE_UNKNOWN" "$MANAGER_UPDATE_STALE" "$MANAGER_UPDATE_CHECK_FAILED" "$MANAGER_UPDATE_ERRORS"
  printf '%-16s %-12s %-18s %-18s %s\n' App State Update Cache Reason
  for record in "${MANAGER_UPDATE_RECORDS[@]}"; do
    printf '%-16s %-12s %-18s %-18s %s\n' \
      "$(state_json_field "$record" app_id)" "$(state_json_field "$record" state)" \
      "$(state_json_field "$record" version.update_state)" "$(state_json_field "$record" version.cache_state)" \
      "$(state_json_field "$record" reason)"
  done
}

manager_update_main() {
  local json=0 refresh=0 no_network=0 include_csv="" exclude_csv="" arg
  while (($#)); do
    arg="$1"; shift
    case "$arg" in
      --json) json=1 ;;
      --refresh) refresh=1 ;;
      --no-network) no_network=1 ;;
      --include) (($#)) || { manager_update_print_usage; return 2; }; include_csv="$1"; shift ;;
      --exclude) (($#)) || { manager_update_print_usage; return 2; }; exclude_csv="$1"; shift ;;
      --include=*) include_csv="${arg#*=}" ;;
      --exclude=*) exclude_csv="${arg#*=}" ;;
      --only-installed|--continue-on-error) ;;
      --help|-h) manager_update_print_usage; return 0 ;;
      *) manager_update_print_usage; return 2 ;;
    esac
  done
  (( refresh && no_network )) && { manager_update_print_usage; return 2; }
  manager_update_collect "$refresh" "$no_network" "$include_csv" "$exclude_csv" || return $?
  if (( json )); then manager_update_render_check_json "$refresh" "$no_network"; else manager_update_render_check_table; fi
  manager_update_collect_status
}

manager_update_plan_record() {
  local record="$1" app_id app_name install_state state reason version_json action
  app_id="$(state_json_field "$record" app_id)"
  app_name="$(state_json_field "$record" app_name)"
  install_state="$(state_json_field "$record" install_state)"
  state="$(state_json_field "$record" state)"
  reason="$(state_json_field "$record" reason)"
  version_json="$(state_json_raw_field "$record" version)" || return 1
  if [[ "$install_state" == installed && "$state" == checked && "$(state_json_field "$record" version.update_state)" == update_available ]]; then
    action=plan
    reason=update_available
  else
    action=skip
    [[ -n "$reason" && "$reason" != null ]] || reason="$(state_json_field "$record" version.update_state)"
  fi
  printf '{"app_id":%s,"app_name":%s,"install_state":%s,"action":%s,"reason":%s,"version":%s}' \
    "$(app_json_string "$app_id")" "$(app_json_string "$app_name")" "$(app_json_string "$install_state")" \
    "$(app_json_string "$action")" "$(app_json_string "$reason")" "$version_json"
}

manager_update_acquire_lock() {
  local lock_file="${DEPLOY_MANAGER_LOCK_FILE:-${DEPLOY_OPERATION_ROOT}/locks/manager.lock}" lock_dir
  lock_dir="$(dirname "$lock_file")"
  [[ ! -L "$lock_dir" ]] || return 1
  mkdir -p "$lock_dir" || return 1
  operation_set_owner_and_mode "$lock_dir" 750 || return 1
  command -v flock >/dev/null 2>&1 || return 1
  exec 8>"$lock_file" || return 1
  operation_set_owner_and_mode "$lock_file" 600 || { exec 8>&-; return 1; }
  flock -n 8 || { exec 8>&-; return 9; }
}

manager_update_release_lock() {
  flock -u 8 2>/dev/null || true
  exec 8>&- 2>/dev/null || true
}

manager_update_confirm() {
  local yes="$1" planned="$2" answer
  [[ "$yes" == 1 || "${DEPLOY_ASSUME_YES:-0}" == 1 ]] && return 0
  if [[ ! -t 0 ]]; then
    echo 'update-all requires --yes or DEPLOY_ASSUME_YES=1 when standard input is not interactive.' >&2
    return 2
  fi
  printf 'Update %s application(s)? [y/N] ' "$planned" >&2
  read -r answer
  [[ "${answer,,}" == y || "${answer,,}" == yes ]]
}

# Run through the normal app dispatcher so each update retains its own app
# operation record and lifecycle lock. The caller deliberately invokes this in
# a subshell so app configuration and traps cannot leak into later targets.
manager_update_execute_app() {
  local app_id="$1"
  manager_load_app "$app_id"
  dispatch_action update
}

manager_update_operation_log() {
  [[ "${MANAGER_UPDATE_OPERATION_ACTIVE:-0}" == 1 ]] || return 0
  local line="$1"
  operation_redact_line "$line" >>"$OPERATION_LOG_PATH" || true
}

manager_update_operation_exit_handler() {
  local status=$?
  [[ "${MANAGER_UPDATE_OPERATION_ACTIVE:-0}" == 1 ]] || return 0
  MANAGER_UPDATE_OPERATION_ACTIVE=0
  operation_step_finish execute failed >/dev/null 2>&1 || true
  operation_finish "$status" "" "update-all exited with status ${status}" >/dev/null 2>&1 || true
}

manager_update_operation_start() {
  operation_start manager "" update-all || return 1
  operation_step_start execute >/dev/null 2>&1 || {
    operation_finish 1 failed "failed to start execute step" >/dev/null 2>&1 || true
    return 1
  }
  MANAGER_UPDATE_OPERATION_ACTIVE=1
  deploy_add_exit_handler manager_update_operation_exit_handler
  manager_update_operation_log "update-all started planned=${MANAGER_UPDATE_PLANNED:-0}"
}

manager_update_operation_finish() {
  local status="$1" summary="${2:-}"
  [[ "${MANAGER_UPDATE_OPERATION_ACTIVE:-0}" == 1 ]] || return 0
  MANAGER_UPDATE_OPERATION_ACTIVE=0
  if (( status == 0 )); then
    operation_step_finish execute succeeded >/dev/null 2>&1 || true
  else
    operation_step_finish execute failed >/dev/null 2>&1 || true
  fi
  operation_finish "$status" "" "$summary" >/dev/null 2>&1 || true
}

manager_update_execution_record() {
  local plan_record="$1" state="$2" status="$3" reason="$4" app_id app_name install_state version_json status_json
  app_id="$(state_json_field "$plan_record" app_id)"
  app_name="$(state_json_field "$plan_record" app_name)"
  install_state="$(state_json_field "$plan_record" install_state)"
  version_json="$(state_json_raw_field "$plan_record" version)" || return 1
  [[ "$status" =~ ^[0-9]+$ ]] && status_json="$status" || status_json=null
  printf '{"app_id":%s,"app_name":%s,"install_state":%s,"state":%s,"status":%s,"reason":%s,"version":%s}' \
    "$(app_json_string "$app_id")" "$(app_json_string "$app_name")" "$(app_json_string "$install_state")" \
    "$(app_json_string "$state")" "$status_json" "$(state_json_nullable "$reason")" "$version_json"
}

manager_update_all_main() {
  local dry_run=0 json=0 refresh=0 no_network=0 yes=0 include_csv="" exclude_csv="" arg record plan_record action
  local planned=0 skipped=0 updated=0 failed=0 first=1 status=0 app_id execution_record
  local -a plan_records=() execution_records=()
  while (($#)); do
    arg="$1"; shift
    case "$arg" in
      --dry-run) dry_run=1 ;;
      --json) json=1 ;;
      --refresh) refresh=1 ;;
      --no-network) no_network=1 ;;
      --yes) yes=1 ;;
      --include) (($#)) || { manager_update_all_print_usage; return 2; }; include_csv="$1"; shift ;;
      --exclude) (($#)) || { manager_update_all_print_usage; return 2; }; exclude_csv="$1"; shift ;;
      --include=*) include_csv="${arg#*=}" ;;
      --exclude=*) exclude_csv="${arg#*=}" ;;
      --only-installed|--continue-on-error) ;;
      --help|-h) manager_update_all_print_usage; return 0 ;;
      *) manager_update_all_print_usage; return 2 ;;
    esac
  done
  (( refresh && no_network )) && { manager_update_all_print_usage; return 2; }
  manager_update_collect "$refresh" "$no_network" "$include_csv" "$exclude_csv" || return $?
  for record in "${MANAGER_UPDATE_RECORDS[@]}"; do
    plan_record="$(manager_update_plan_record "$record")" || return 1
    action="$(state_json_field "$plan_record" action)"
    [[ "$action" == plan ]] && planned=$((planned + 1)) || skipped=$((skipped + 1))
    plan_records+=("$plan_record")
  done

  if (( dry_run )); then
    if (( json )); then
      printf '{"schema_version":1,"generated_at":%s,"dry_run":true,"refresh":%s,"no_network":%s,"summary":{"selected":%s,"planned":%s,"skipped":%s,"check_failed":%s,"errors":%s},"records":[' \
        "$(app_json_string "$(state_now)")" "$([[ "$refresh" == 1 ]] && printf true || printf false)" "$([[ "$no_network" == 1 ]] && printf true || printf false)" \
        "$MANAGER_UPDATE_SELECTED" "$planned" "$skipped" "$MANAGER_UPDATE_CHECK_FAILED" "$MANAGER_UPDATE_ERRORS"
      for plan_record in "${plan_records[@]}"; do (( first )) || printf ','; first=0; printf '%s' "$plan_record"; done
      printf ']}\n'
    else
      printf 'update-all dry-run: selected=%s planned=%s skipped=%s check_failed=%s errors=%s\n' \
        "$MANAGER_UPDATE_SELECTED" "$planned" "$skipped" "$MANAGER_UPDATE_CHECK_FAILED" "$MANAGER_UPDATE_ERRORS"
      printf '%-16s %-10s %-18s %s\n' App Action Update Reason
      for plan_record in "${plan_records[@]}"; do
        printf '%-16s %-10s %-18s %s\n' \
          "$(state_json_field "$plan_record" app_id)" "$(state_json_field "$plan_record" action)" \
          "$(state_json_field "$plan_record" version.update_state)" "$(state_json_field "$plan_record" reason)"
      done
    fi
    manager_update_collect_status
    return $?
  fi

  if (( planned > 0 )); then
    if (( json )) && [[ "$yes" != 1 && "${DEPLOY_ASSUME_YES:-0}" != 1 ]]; then
      echo 'update-all --json with planned updates requires --yes or DEPLOY_ASSUME_YES=1.' >&2
      return 2
    fi
    manager_update_confirm "$yes" "$planned" || return $?
    manager_update_acquire_lock
    status=$?
    if (( status != 0 )); then
      echo 'Unable to acquire the manager update lock.' >&2
      return "$status"
    fi
    MANAGER_UPDATE_PLANNED="$planned"
    manager_update_operation_start || {
      (( planned > 0 )) && manager_update_release_lock
      echo 'Unable to start manager update operation record.' >&2
      return 1
    }
  fi
  for plan_record in "${plan_records[@]}"; do
    action="$(state_json_field "$plan_record" action)"
    if [[ "$action" != plan ]]; then
      execution_records+=("$(manager_update_execution_record "$plan_record" skipped "" "$(state_json_field "$plan_record" reason)")")
      continue
    fi
    app_id="$(state_json_field "$plan_record" app_id)"
    if (( json )); then
      if ( manager_update_execute_app "$app_id" ) >&2; then status=0; else status=$?; fi
    else
      printf '\n== Updating %s ==\n' "$app_id"
      if ( manager_update_execute_app "$app_id" ); then status=0; else status=$?; fi
    fi
    if (( status == 0 )); then
      updated=$((updated + 1))
      execution_records+=("$(manager_update_execution_record "$plan_record" succeeded "$status" "")")
      manager_update_operation_log "app=${app_id} state=succeeded status=${status}"
    else
      failed=$((failed + 1))
      execution_records+=("$(manager_update_execution_record "$plan_record" failed "$status" "update_failed")")
      manager_update_operation_log "app=${app_id} state=failed status=${status}"
    fi
  done
  (( planned > 0 )) && manager_update_release_lock
  if (( failed == 0 )); then
    manager_update_operation_finish 0 "update-all completed successfully"
  else
    manager_update_operation_finish 1 "update-all completed with ${failed} failed application(s)"
  fi

  if (( json )); then
    first=1
    printf '{"schema_version":1,"generated_at":%s,"dry_run":false,"refresh":%s,"no_network":%s,"summary":{"selected":%s,"planned":%s,"updated":%s,"failed":%s,"skipped":%s,"check_failed":%s,"errors":%s},"records":[' \
      "$(app_json_string "$(state_now)")" "$([[ "$refresh" == 1 ]] && printf true || printf false)" "$([[ "$no_network" == 1 ]] && printf true || printf false)" \
      "$MANAGER_UPDATE_SELECTED" "$planned" "$updated" "$failed" "$skipped" "$MANAGER_UPDATE_CHECK_FAILED" "$MANAGER_UPDATE_ERRORS"
    for execution_record in "${execution_records[@]}"; do (( first )) || printf ','; first=0; printf '%s' "$execution_record"; done
    printf ']}\n'
  else
    printf '\nupdate-all: selected=%s planned=%s updated=%s failed=%s skipped=%s check_failed=%s errors=%s\n' \
      "$MANAGER_UPDATE_SELECTED" "$planned" "$updated" "$failed" "$skipped" "$MANAGER_UPDATE_CHECK_FAILED" "$MANAGER_UPDATE_ERRORS"
  fi
  (( failed == 0 )) || return 1
  manager_update_collect_status
}

# ----- lib/app.sh -----

# Strict-ASCII validators must stay ASCII-only on every server locale:
# character classes such as [A-Za-z] are collation-dependent and, under UTF-8
# locales, also match accented Latin characters (for example é). Each
# validator pins LC_ALL=C so validation is byte-exact regardless of locale.
# Validate a port number is in range 1-65535.
app_validate_port() {
  local value="$1"
  local label="${2:-port}"
  if ! [[ "$value" =~ ^[0-9]+$ ]] || [[ "$value" -lt 1 || "$value" -gt 65535 ]]; then
    error "$(t error.port_invalid "$label" "$value")"
  fi
}

# Validate a boolean value.
app_validate_bool() {
  local name="$1" value="$2"
  case "${value,,}" in
    1|0|true|false|yes|no|y|n|on|off) ;;
    *) error "$(t error.bool_invalid "$name" "$value")" ;;
  esac
}

# Validate an optional domain name (empty string is allowed).
app_validate_domain() {
  local name="$1" value="$2"
  if [[ -n "$value" ]] && ! is_valid_dns_name "$value"; then
    error "$(t error.domain_invalid "$name" "$value")"
  fi
}

app_validate_http_url() {
  local name="$1" value="$2" scheme host
  case "$value" in
    http://*|https://*) ;;
    *) error "$(t error.url_invalid "$name" "$value")" ;;
  esac
  case "$value" in
    ""|*[[:space:]]*|*\"*|*"'"*|*"\\"*|*"<"*|*">"*|*"\`"*|*"|"*)
      error "$(t error.url_invalid "$name" "$value")"
      ;;
  esac
  scheme="${value%%://*}"
  host="${value#"${scheme}"://}"
  host="${host%%/*}"
  host="${host%%:*}"
  if [[ "$host" != "localhost" && ! "$host" =~ ^[0-9]+(\.[0-9]+){3}$ ]] && ! is_valid_dns_name "$host"; then
    error "$(t error.url_invalid "$name" "$value")"
  fi
}

app_validate_https_url() {
  local name="$1" value="$2"
  app_validate_http_url "$name" "$value"
  if [[ "$value" != https://* ]]; then
    error "$(t error.https_url_invalid "$name" "$value")"
  fi
}

app_validate_goproxy() {
  local name="$1" value="$2" token
  local -a _goproxy_parts
  [[ -n "$value" ]] || error "$(t error.goproxy_invalid "$name" "$value")"
  case "$value" in
    *[[:space:]]*|*\"*|*"'"*|*"\\"*|*"<"*|*">"*|*"\`"*)
      error "$(t error.goproxy_invalid "$name" "$value")"
      ;;
  esac
  local normalized="${value//|/,}"
  IFS=',' read -r -a _goproxy_parts <<< "$normalized"
  for token in "${_goproxy_parts[@]}"; do
    case "$token" in
      direct|off) ;;
      http://*|https://*)
        app_validate_http_url "$name" "$token"
        ;;
      *)
        error "$(t error.goproxy_invalid "$name" "$value")"
        ;;
    esac
  done
}

app_validate_image_repo() {
  local name="$1" value="$2" first rest part
  # Character ranges in regexes are collation-dependent: under en_US.UTF-8 /
  # zh_CN.UTF-8, [a-z0-9] also matches uppercase. Pin the C locale so image
  # repo validation accepts lowercase-only names on every server locale.
  local LC_ALL=C
  local -a _image_repo_parts
  [[ -n "$value" ]] || error "$(t error.image_repo_invalid "$name" "$value")"
  case "$value" in
    *[[:space:]]*|*\"*|*"'"*|*"\\"*|*"<"*|*">"*|*"\`"*|*"|"*|*";"*|*"&"*|*'$'*|*"("*|*")"*|*"["*|*"]"*|*"{"*|*"}"*|*"!"*|*"?"*|*"*"*|*@*)
      error "$(t error.image_repo_invalid "$name" "$value")"
      ;;
  esac
  [[ "$value" != /* && "$value" != */ && "$value" != *//* && "$value" != *..* ]] \
    || error "$(t error.image_repo_invalid "$name" "$value")"

  first="${value%%/*}"
  rest="$value"
  if [[ "$first" == *.* || "$first" == *:* || "$first" == localhost ]]; then
    [[ "$value" == */* ]] || error "$(t error.image_repo_invalid "$name" "$value")"
    [[ "$first" =~ ^[a-z0-9]([a-z0-9.-]*[a-z0-9])?(:[0-9]+)?$ ]] \
      || error "$(t error.image_repo_invalid "$name" "$value")"
    if [[ "$first" == *:* ]]; then
      local port="${first##*:}"
      [[ "$port" =~ ^[0-9]+$ && "$port" -ge 1 && "$port" -le 65535 ]] \
        || error "$(t error.image_repo_invalid "$name" "$value")"
    fi
    rest="${value#*/}"
  fi

  IFS='/' read -r -a _image_repo_parts <<< "$rest"
  for part in "${_image_repo_parts[@]}"; do
    [[ "$part" =~ ^[a-z0-9]+([._-][a-z0-9]+)*$ ]] \
      || error "$(t error.image_repo_invalid "$name" "$value")"
  done
}

app_validate_image_tag() {
  local name="$1" value="$2"
  local LC_ALL=C
  if ! [[ "$value" =~ ^[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}$ ]]; then
    error "$(t error.image_tag_invalid "$name" "$value")"
  fi
}

app_validate_sha256() {
  local name="$1" value="$2"
  local LC_ALL=C
  if ! [[ "$value" =~ ^[A-Fa-f0-9]{64}$ ]]; then
    error "$(t error.sha256_invalid "$name" "$value")"
  fi
}

app_is_valid_email() {
  local value="${1:-}" local_part domain
  local LC_ALL=C
  [[ -n "$value" && ${#value} -le 254 ]] || return 1
  case "$value" in
    *[[:space:]]*|*\"*|*"'"*|*"\\"*|*"<"*|*">"*|*"\`"*|*"|"*|*";"*|*"&"*|*'$'*|*"("*|*")"*|*"["*|*"]"*|*"{"*|*"}"*|*"!"*|*"?"*|*"*"*|*/*|*@*@*)
      return 1
      ;;
  esac
  [[ "$value" == *@* ]] || return 1
  local_part="${value%@*}"
  domain="${value#*@}"
  [[ -n "$local_part" && ${#local_part} -le 64 ]] || return 1
  [[ "$local_part" != .* && "$local_part" != *. && "$local_part" != *..* ]] || return 1
  [[ "$local_part" =~ ^[A-Za-z0-9._%+-]+$ ]] || return 1
  is_valid_dns_name "$domain"
}

app_validate_email() {
  local name="$1" value="$2"
  if ! app_is_valid_email "$value"; then
    error "$(t error.email_invalid "$name" "$value")"
  fi
}

app_validate_release_version() {
  local name="$1" value="$2"
  local LC_ALL=C
  if ! [[ "$value" =~ ^[0-9]+[.][0-9]+([.][0-9]+)?([-.][A-Za-z0-9][A-Za-z0-9_.-]*)?$ ]]; then
    error "$(t error.release_version_invalid "$name" "$value")"
  fi
}

app_validate_system_name() {
  local name="$1" value="$2"
  local LC_ALL=C
  if ! [[ "$value" =~ ^[A-Za-z_][A-Za-z0-9_-]{0,63}$ ]]; then
    error "$(t error.system_name_invalid "$name" "$value")"
  fi
}

app_validate_systemd_name() {
  local name="$1" value="$2"
  local LC_ALL=C
  if ! [[ "$value" =~ ^[A-Za-z0-9_.@-]+$ ]] \
      || [[ "$value" == .* || "$value" == *. || "$value" == *..* || "$value" == *"/"* ]]; then
    error "$(t error.systemd_name_invalid "$name" "$value")"
  fi
}

app_validate_github_repo() {
  local name="$1" value="$2"
  local LC_ALL=C
  if ! [[ "$value" =~ ^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$ ]] \
      || [[ "$value" == *..* || "$value" == .* || "$value" == */.* || "$value" == *. || "$value" == *.*/ ]]; then
    error "$(t error.github_repo_invalid "$name" "$value")"
  fi
}

app_validate_git_ref() {
  local name="$1" value="$2"
  local LC_ALL=C
  if ! [[ "$value" =~ ^[A-Za-z0-9._/-]+$ ]] \
      || [[ "$value" == -* || "$value" == */ || "$value" == *. || "$value" == *..* || "$value" == *@\{* || "$value" == *//* ]]; then
    error "$(t error.git_ref_invalid "$name" "$value")"
  fi
}

app_validate_db_identifier() {
  local name="$1" value="$2"
  local LC_ALL=C
  if ! [[ "$value" =~ ^[A-Za-z_][A-Za-z0-9_]{0,62}$ ]]; then
    error "$(t error.db_identifier_invalid "$name" "$value")"
  fi
}

# Echo the standard deployment config path for the current app.
app_conf_file() {
  local standard="/etc/${APP_ID:-app}-deploy.conf"
  if [[ -n "${_APP_CONF_LEGACY:-}" ]]; then
    echo "$_APP_CONF_LEGACY"
  else
    echo "$standard"
  fi
}

# Echo the standard lock file path for the current app.
app_lock_file() {
  echo "/var/lock/${APP_ID:-app}-deploy.lock"
}

# Standard config save — writes CONFIG_KEYS to the app conf file.
app_save_config() {
  local conf_file
  conf_file="$(app_conf_file)"
  if ! write_config_file "$conf_file" "${CONFIG_KEYS[@]}"; then
    error "$(t error.config_write "$conf_file")"
  fi
  success "$(t config.saved "$conf_file")"
}

# Standard config load — loads from the app conf file, then calls
# an optional hook to recompute derived paths, and re-validates if a
# _validate_config_values function exists.
# Usage: app_load_config [derive_hook_fn]
app_load_config() {
  local conf_file derive_hook
  conf_file="$(app_conf_file)"
  derive_hook="${1:-}"
  [[ -f "$conf_file" ]] || return 0
  load_config_file "$conf_file" "${CONFIG_KEYS[@]}"
  if [[ -n "$derive_hook" ]] && declare -f "$derive_hook" >/dev/null 2>&1; then
    "$derive_hook"
  fi
  if declare -f _validate_config_values >/dev/null 2>&1; then
    _validate_config_values
  fi
  success "$(t config.loaded "$conf_file")"
}

# Register a legacy config path so app_conf_file() returns it during
# load when the old file still exists on disk.
app_conf_register_legacy() {
  local legacy="$1"
  if [[ -f "$legacy" ]]; then
    _APP_CONF_LEGACY="$legacy"
  fi
}

deploy_env_truthy() {
  local name="$1"
  local value="${!name:-}"
  case "${value,,}" in
    1|true|yes|y|on) return 0 ;;
    *) return 1 ;;
  esac
}

deploy_assume_yes() {
  deploy_env_truthy DEPLOY_ASSUME_YES
}

app_doctor_service_name() {
  if [[ -n "${APP_DOCTOR_SERVICE_FN:-}" ]] && declare -f "$APP_DOCTOR_SERVICE_FN" >/dev/null 2>&1; then
    "$APP_DOCTOR_SERVICE_FN" && return 0
    return 1
  fi
  if [[ -n "${SERVICE_NAME:-}" ]]; then
    printf '%s\n' "$SERVICE_NAME"
    return 0
  fi
  return 1
}

# The config-derive hook is app-declared: an app that derives paths from
# saved configuration sets APP_CONFIG_DERIVE_HOOK to its hook function name.
app_doctor_config_derive_hook() {
  local hook="${APP_CONFIG_DERIVE_HOOK:-}"
  if [[ -n "$hook" ]] && declare -f "$hook" >/dev/null 2>&1; then
    printf '%s\n' "$hook"
    return 0
  fi
  return 1
}
app_doctor_validate_saved_config() {
  local conf_file="$1"
  (
    load_config_file "$conf_file" "${CONFIG_KEYS[@]}"
    local derive_hook=""
    if derive_hook="$(app_doctor_config_derive_hook 2>/dev/null)"; then
      "$derive_hook"
    fi
    if declare -f _validate_config_values >/dev/null 2>&1; then
      _validate_config_values
    fi
  )
}

app_json_string() {
  local value="${1:-}"
  value="${value//\\/\\\\}"
  value="${value//\"/\\\"}"
  value="${value//$'\b'/\\b}"
  value="${value//$'\f'/\\f}"
  value="${value//$'\n'/\\n}"
  value="${value//$'\r'/\\r}"
  value="${value//$'\t'/\\t}"
  # Escape the remaining C0 control characters (U+0001..U+001F), which JSON
  # forbids literally. NUL (U+0000) cannot appear in bash strings. Do this
  # unconditionally: Bash regex ranges over control bytes vary across builds.
  local i byte hex octal
  for ((i = 1; i < 32; i++)); do
    case "$i" in 8|9|10|12|13) continue ;; esac
    printf -v octal '%03o' "$i"
    printf -v byte '%b' "\0$octal"
    printf -v hex '%02x' "$i"
    value="${value//"$byte"/"\u00${hex}"}"
  done
  printf '"%s"' "$value"
}

app_json_bool() {
  if [[ "${1:-false}" == "true" ]]; then
    printf 'true'
  else
    printf 'false'
  fi
}

app_json_value() {
  local value="${1:-}"
  case "$value" in
    true|false|null) printf '%s' "$value" ;;
    *) app_json_string "$value" ;;
  esac
}

# Emit one JSON service object for a systemd unit name.
app_json_service_object() {
  local service_name="$1"
  local unit_exists=null active=null enabled=null
  if command -v systemctl >/dev/null 2>&1; then
    if systemctl list-unit-files "${service_name}.service" --no-legend 2>/dev/null | grep -q .; then
      unit_exists=true
      if systemctl is-active --quiet "$service_name" 2>/dev/null; then
        active=true
      else
        active=false
      fi
      if systemctl is-enabled --quiet "$service_name" 2>/dev/null; then
        enabled=true
      else
        enabled=false
      fi
    else
      unit_exists=false
    fi
  fi
  printf '{"name":%s,"unit_exists":%s,"active":%s,"enabled":%s}' \
    "$(app_json_string "$service_name")" \
    "$(app_json_value "$unit_exists")" \
    "$(app_json_value "$active")" \
    "$(app_json_value "$enabled")"
}

# Print the INSTALLED_VERSION recorded in a deployment config file, if any.
app_config_installed_version() {
  local conf_file="$1"
  [[ -f "$conf_file" ]] || return 1
  local value
  value="$(awk -F= '
      /^[[:space:]]*INSTALLED_VERSION=/ {
        sub(/^[^=]*=[[:space:]]*/, "")
        gsub(/^"|"$/, "")
        gsub(/[[:space:]]+$/, "")
        print
        exit
      }
    ' "$conf_file" 2>/dev/null)" || return 1
  [[ -n "$value" ]] || return 1
  printf '%s\n' "$value"
}

do_status_json() {
  app_status_collect_json
}

# Writes an Nginx site config from stdin through an atomic helper.
app_write_nginx_config_file() {
  local nginx_conf="$1" error_key="$2"
  if ! atomic_write_file "$nginx_conf" 644 root:root; then
    error "$(t "$error_key" "$nginx_conf")"
  fi
}

# Creates an Nginx sites-enabled symlink atomically.
app_write_nginx_site_link() {
  local target="$1" link_path="$2" error_key="$3"
  if ! atomic_symlink "$target" "$link_path"; then
    error "$(t "$error_key" "$target")"
  fi
}

# Writes a per-app logrotate policy for the service log directory, staging the
# file through atomic_write_file. The log directory, target file, and localized
# error/success keys are app-supplied.
app_write_logrotate() {
  local logrotate_file="$1" log_dir="$2" error_key="$3" success_key="$4"
  if ! atomic_write_file "$logrotate_file" 644 root:root << LOGR
${log_dir}/*.log {
    daily
    rotate 14
    compress
    delaycompress
    missingok
    notifempty
    # copytruncate avoids requiring SIGHUP support from the service.
    # A tiny number of log lines can be lost during rotation.
    copytruncate
}
LOGR
  then
    error "$(t "$error_key")"
  fi
  success "$(t "$success_key")"
}

# Opens the service port through the active firewall manager: ufw first, then
# optionally firewalld (opt-in for apps that support it), then iptables with
# persistence. Localized keys are addressed through the app key prefix and the
# app label appears in the ufw rule comment.
app_configure_firewall() {
  local port="$1" app_prefix="$2" app_label="$3" enable_firewalld="${4:-false}"
  local FW_DONE=false FW_ERROR=false
  if command -v ufw &>/dev/null && ufw status 2>/dev/null | grep -q "Status: active"; then
    if ufw allow "${port}/tcp" comment "$app_label" > /dev/null; then
      success "$(t "${app_prefix}.success.ufw_port" "$port")"
      FW_DONE=true
    else
      FW_ERROR=true
    fi
  fi
  if $enable_firewalld && ! $FW_DONE && command -v firewall-cmd &>/dev/null && \
      firewall-cmd --state &>/dev/null; then
    if firewall-cmd --permanent --add-port="${port}/tcp" >/dev/null 2>&1 \
        && firewall-cmd --reload >/dev/null 2>&1; then
      success "$(t "${app_prefix}.success.firewalld_port" "$port")"
      FW_DONE=true
    else
      FW_ERROR=true
    fi
  fi
  if ! $FW_DONE && command -v iptables &>/dev/null; then
    if iptables -C INPUT -p tcp --dport "$port" -j ACCEPT 2>/dev/null \
        || iptables -A INPUT -p tcp --dport "$port" -j ACCEPT; then
      if command -v netfilter-persistent &>/dev/null; then
        if netfilter-persistent save 2>/dev/null; then
          success "$(t "${app_prefix}.success.iptables_saved")"
        else
          warn "$(t "${app_prefix}.warn.iptables_not_persisted")"
        fi
      elif command -v iptables-save &>/dev/null; then
        local iptables_dir="/etc/iptables"
        if mkdir -p "$iptables_dir"; then
          local iptables_rules="${iptables_dir}/rules.v4"
          local iptables_tmp
          if ! iptables_tmp=$(mktemp "${iptables_rules}.XXXXXX"); then
            warn "$(t "${app_prefix}.warn.iptables_write_failed")"
          elif iptables-save > "$iptables_tmp" 2>/dev/null \
              && chmod 644 "$iptables_tmp" \
              && chown root:root "$iptables_tmp" \
              && mv "$iptables_tmp" "$iptables_rules"; then
            info "$(t "${app_prefix}.info.iptables_rules_written")"
          else
            rm -f "$iptables_tmp"
            warn "$(t "${app_prefix}.warn.iptables_write_failed")"
          fi
        else
          warn "$(t "${app_prefix}.warn.iptables_write_failed")"
        fi
      else
        warn "$(t "${app_prefix}.warn.iptables_not_persisted")"
      fi
      success "$(t "${app_prefix}.success.iptables_port" "$port")"
      FW_DONE=true
    else
      FW_ERROR=true
    fi
  fi
  if ! $FW_DONE; then
    if $FW_ERROR; then
      warn "$(t "${app_prefix}.warn.firewall_config_failed" "$port")"
    else
      warn "$(t "${app_prefix}.warn.no_firewall" "$port")"
    fi
  fi
}

do_doctor() {
  local failures=0 warnings=0

  doctor_ok() { success "$*"; }
  doctor_warn() { warnings=$((warnings + 1)); warn "$*"; }
  doctor_fail() {
    failures=$((failures + 1))
    echo -e "${RED}[x]${NC} $*" >&2
  }

  show_banner
  step "$(t doctor.title)"

  if [[ ${EUID:-$(id -u)} -eq 0 ]]; then
    doctor_ok "$(t doctor.root_ok)"
  else
    doctor_warn "$(t doctor.root_warn)"
  fi

  local conf_file
  conf_file="$(app_conf_file)"
  local conf_safe=false
  if [[ -f "$conf_file" ]]; then
    local conf_owner="unknown" conf_mode="unknown"
    # GNU stat (coreutils) is assumed: -c '%U'/'%a' is not portable to BSD stat.
    if command -v stat >/dev/null 2>&1; then
      conf_owner="$(stat -c '%U' "$conf_file" 2>/dev/null || echo unknown)"
      conf_mode="$(stat -c '%a' "$conf_file" 2>/dev/null || echo unknown)"
    fi
    if [[ "$conf_owner" != "root" ]]; then
      doctor_fail "$(t doctor.config_owner_bad "$conf_owner" "$conf_file")"
    elif [[ "$conf_mode" != "600" && "$conf_mode" != "400" ]]; then
      doctor_fail "$(t doctor.config_mode_bad "$conf_mode" "$conf_file")"
    else
      doctor_ok "$(t doctor.config_ok "$conf_file")"
      conf_safe=true
    fi
    if $conf_safe; then
      if app_doctor_validate_saved_config "$conf_file"; then
        doctor_ok "$(t doctor.config_parse_ok "$conf_file")"
      else
        doctor_fail "$(t doctor.config_parse_bad "$conf_file")"
      fi
    fi
  else
    doctor_warn "$(t doctor.config_missing "$conf_file")"
  fi

  local cmd
  for cmd in bash awk sed grep mktemp; do
    if command -v "$cmd" >/dev/null 2>&1; then
      doctor_ok "$(t doctor.command_ok "$cmd")"
    else
      doctor_fail "$(t doctor.command_missing "$cmd")"
    fi
  done
  for cmd in curl systemctl; do
    if command -v "$cmd" >/dev/null 2>&1; then
      doctor_ok "$(t doctor.command_ok "$cmd")"
    else
      doctor_warn "$(t doctor.command_missing "$cmd")"
    fi
  done

  local service_name=""
  if service_name="$(app_doctor_service_name 2>/dev/null)"; then
    if command -v systemctl >/dev/null 2>&1; then
      if systemctl list-unit-files "${service_name}.service" --no-legend 2>/dev/null | grep -q .; then
        if systemctl is-active --quiet "$service_name" 2>/dev/null; then
          doctor_ok "$(t doctor.service_active "$service_name")"
        else
          doctor_warn "$(t doctor.service_inactive "$service_name")"
        fi
        if systemctl is-enabled --quiet "$service_name" 2>/dev/null; then
          doctor_ok "$(t doctor.service_enabled "$service_name")"
        else
          doctor_warn "$(t doctor.service_disabled "$service_name")"
        fi
      else
        doctor_warn "$(t doctor.service_unit_missing "$service_name")"
      fi
    else
      doctor_warn "$(t doctor.systemctl_missing)"
    fi
  fi

  if [[ "$failures" -gt 0 ]]; then
    echo -e "${RED}[x]${NC} $(t doctor.done_warn "$failures" "$warnings")" >&2
    return 1
  fi
  if [[ "$warnings" -gt 0 ]]; then
    doctor_warn "$(t doctor.done_warn "$failures" "$warnings")"
  else
    doctor_ok "$(t doctor.done_ok)"
  fi
}

# ----- lib/binary_app.sh -----

# Shared lifecycle for GitHub-release single-binary services.
#
# A binary app provides BA_* configuration variables, optional hook
# functions (ba_asset_name, ba_download_urls, ba_write_config,
# ba_systemd_unit, bapp_health_probe, ba_status_extra, ba_uninstall_extra,
# ba_validate_extra, ba_preflight_extra, ba_pre_start, ba_summary_extra),
# then calls binary_app_bootstrap.  The bapp_* functions implement the
# lifecycle; each thin impl/install_<app>.sh defines the standard command
# functions (do_install, do_update, do_backup, do_status, do_uninstall) as
# short delegates that acquire the deployment lock, plus app-specific
# download, config, and runtime hooks.

i18n_register_many \
  binary_app.error.apt_only \
  "This script only supports Debian / Ubuntu because apt-get was not found." \
  "此脚本仅支持 Debian / Ubuntu（apt-get 未找到）。" \
  binary_app.error.arch \
  "Unsupported architecture: %s. Supported: x86_64 / aarch64." \
  "不支持的架构：%s（支持 x86_64 / aarch64）。" \
  binary_app.error.github_unreachable \
  "Cannot reach GitHub. Check network/proxy settings and retry." \
  "网络不通，无法访问 GitHub，请检查网络或代理后重试。" \
  binary_app.warn.github_api \
  "Cannot reach GitHub API." \
  "无法访问 GitHub API。" \
